window.__LEX={"G4600":"<h1>siagon</h1>\n<p>Strong n° 4600 <i>Prononciation [see-ag-one']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>la mâchoire, l'os de la mâchoire, la joue</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σιαγών, όνος (ἡ)</b> <span>[ᾱ]</span> mâchoire, <i>p. ext</i>. joue, HPC. <i>Epid. 3, 1096 ;</i> SOPH. <i>fr. 114 ;</i> AR. <i>fr. 278 Dind. ;</i> ARSTT. <i>P.A. 3, 7, 4, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. σιηγών, HPC. <i>l. c</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σιαγων - σιαγών</font>\n<br><br>de dérivation incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G4601":"<h1>sigao</h1>\n<p>Strong n° 4601 <i>Prononciation [see-gah'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>garder le silence, se tenir en paix</li>\n<li>être mis au silence, être enfermé, caché</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σιγάω</b> <span>[ῑ]</span> <span>(<i>impf</i>. ἐσίγων, <i>f</i>. σιγήσομαι, <i>réc</i>. σιγήσω, <i>ao</i>. ἐσίγησα, <i>pf</i>. σεσίγηκα ; <i>pass. f</i>. σιγηθήσομαι, <i>ao</i>. ἐσιγήθην, <i>pf</i>. σεσίγημαι, <i>f. ant</i>. σεσιγήσομαι)</span><br><b>   I <i>intr.</i></b> se taire, garder le silence, <i>dans Hom. seul. à l’impér</i>. σίγα, IL. <i>14, 90 ;</i> OD. <i>17, 393,</i> silence ! tais-toi ! <i>et à l’inf. prés</i>. HH. <i>Merc. 93 ;</i> σ. περί τινος, EUR. <i>Hipp. 312,</i> se taire au sujet de qqe ch. ; πρός τινα, PLAT. <i>Phædr. 276</i> a, à l’égard de qqn ; πρός τι, XÉN. <i>Cyr. 5, 5, 20,</i> à l’égard de qqe ch. : σιγᾶν σιώπην, EUR. <i>Suppl. 298,</i> garder le silence, rester silencieux ; <i>en parl. de choses (flûtes,</i> ESCHL. <i>Suppl. 181 ; air,</i> EUR. <i>Bacch. 1084 ; mer, etc</i>. THCR. <i>Idyl. 2, 38, etc</i>.) ;<br><b>   II <i>tr</i>.<br>      1</b> taire, garder secret, <i>acc</i>. PD. <i>fr. 49 ;</i> HDT. <i>7, 104 ;</i> ESCHL. <i>Pr. 106, etc. ; d’où au pass</i>. être tu, être gardé secret, PD. <i>O. 9, 156 ;</i> HDT. <i>5, 21 ;</i> SOPH. <i>fr. 585, etc. ;</i><br><b>      2</b> rendre silencieux, <i>d’où au pass</i>. devenir silencieux, EUR. <i>Alc. 78</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Act. prés. ind. 3 sg</i>. σιγῇ <i>et 3 pl</i>. σιγῶντι, THCR. <i>Idyl. 2, 38 ; inf. dor</i>. σιγῆν, EPICH. <i>fr. 130 Ahrens ; part. ion</i>. σιγέων, HDT. <i>8, 26. Ao. sbj. dor</i>. σιγάσω <span>[ᾱ]</span> EUR. <i>Ion 859. Pass. ao. dor</i>. ἐσιγάθην <span>[ᾱ]</span> EUR. <i>Ph. 349 ;</i> THCR. <i>Idyl. 16, 54 ; pf. part</i>. σεσιγαμένος <span>[ᾱ]</span> PD. <i>l. c</i>.<br><span><b>Étym</b>. σιγή.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σιαγω - σιγάω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td> – décrit une condition tranquille en général, incluant le silence\n<br><br> – décrit une condition mentale et ses manifestations, spéc. dans le mutisme (silence à cause de crainte, chagrin, terrible anxiété, etc.)\n<br><br> – est le terme le plus physique et externe, il indique l'abstinence de parole</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n9 fois dans 9 versets de 4 livres bibliques (NT)\n<ul>\n<li>Luc (2)</li>\n<li>Actes (3)</li>\n<li>Romains (1)</li>\n<li>1 Corinthiens (3)</li>\n</ul>\n</td></tr>\n</table>","G4602":"<h1>sige</h1>\n<p>Strong n° 4602 <i>Prononciation [see-gay']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>silence</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σιγή, ῆς (ἡ)</b> <span>[ῑ]</span><br><b>      1</b> silence, <i>dans Hom. seul. au dat. adv</i>. σιγῇ, en silence, IL. <i>19, 255, etc. ; ou</i> σιγῇ νῦν, OD. <i>15, 440,</i> silence ! σιγὴν ἔχειν, HDT. <i>1, 86, ou</i> φυλάσσειν, EUR. <i>I.A. 542,</i> garder le silence ; σιγῇ ἔχειν τι, HDT. <i>9, 93,</i> taire qqe ch. ; <i>au plur</i>. PLAT. <i>Rsp. 425</i> b ; <i>en parl. du silence du vent,</i> EUR. <i>I.A. 10 ; adv</i>. διὰ σιγῆς, PLAT. <i>Gorg. 450</i> c ; <i>ou</i> μετὰ σιγῆς, PLAT. <i>Soph. 264</i> a, en silence ; <i>p. suite,</i> σιγῇ, secrètement, tranquillement, en silence, SOPH. <i>O.R. 341, etc.,</i> XÉN. <i>Mem. 1, 1, 19, etc. ; avec un gén</i>. σιγῇ τινος, HDT. <i>2, 140 ;</i> EUR. <i>Med. 587,</i> à l’insu de qqn ;<br><b>      2</b> réserve silencieuse, discrétion, SOPH. <i>Aj. 293</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dor</i>. σιγά <span>[ᾱ]</span> PD. <i>l. c., etc</i>.<br><span><b>Étym</b>. <i>incert</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σιγη - σιγή</font>\n<br><br>vient apparemment de sizo (siffler, c.à.d. chut!)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G4603":"<h1>sidereos</h1>\n<p>Strong n° 4603 <i>Prononciation [sid-ay'-reh-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>fait de fer</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σιδηροῦς, ᾶ, οῦν</b>, <i>v</i>. σιδήρεος.<br><br>\n<b>σιδήρεος, α, ον</b>, <i>p. contr. att</i>. <b>σιδηροῦς, ᾶ, οῦν</b> <span>[ῐ]</span><br><b>   I</b> de fer, IL. <i>5, 723 ;</i> HDT. <i>1, 25 ;</i> ATT. <i>etc. ;</i> χεὶρ σιδηρᾶ, THC. <i>4, 25 ; 7, 62,</i> grappin de fer ; σιδήρεος οὐρανός, OD. <i>15, 329 ; 17, 565,</i> le ciel de fer, <i>les anciens Grecs supposant que la voûte du ciel était métallique ;</i> οἱ σιδάρεοι, AR. <i>Nub. 249 ;</i> PLAT. COM. <i>2-2, 649 Mein. ;</i> STRATT. (<i>Com. fr. 2, 775</i>) monnaie de fer byzantine ;<br><b>   II</b> <i>p. ext</i>. dur comme le fer <i>au propre,</i> THCR. <i>Idyl. 22, 47 ; fig. :</i><br><b>      1</b> <i>en mauv. part :</i> sec, raide, AR. <i>Ach. 496 ;</i> PLAT. <i>Gorg. 509</i> a, <i>etc. ;</i><br><b>      2</b> dur, cruel, inflexible, IL. <i>24, 205 ;</i> OD. <i>4, 293 ; 5, 191, etc. ;</i><br><b>      3</b> <i>en b. part,</i> ferme, indomptable, IL. <i>22, 357 ;</i> OD. <i>23, 172</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Fém. ion</i>. σιδηρέη, OD. <i>4, 293, etc. Dor</i>. σιδάρεος, AR. THCR. <i>Idyl. ll. cc. Dans les inscr. att. la forme contr</i>. σιδηρᾶ, CIA. <i>2, 807, b, 96 (330 av. J.C.) ; v. Meisterh. p. 117, 4</i>.<br><span><b>Étym</b>. σίδηρος ; <i>cf</i>. σιδήρειος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σιδηρεος - σιδηροῦς</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 2 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>Apocalypse (4)</li>\n</ul>\n</td></tr>\n</table>","G4604":"<h1>sideros</h1>\n<p>Strong n° 4604 <i>Prononciation [sid'-ay-ros]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>fer</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σίδηρος, ου (ὁ)</b> <span>[ῐ]</span><br><b>   I</b> fer, IL. <i>4, 485 ; 5, 723 ; 6, 46 ; 9, 366, etc. ;</i> OD. <i>1, 184, etc. ;</i> HÉS. <i>O. 150, etc. ;</i> ESCHL. <i>Sept. 817, etc. ;</i> ATT. <i>etc. ; fig. comme synon. de dureté, de fermeté,</i> IL. <i>4, 509 ; 20, 372, etc. ;</i> OD. <i>19, 211, etc. ;</i> PD. <i>fr. 88 ;</i> SOPH. <i>fr. 573 ;</i> PLAT. <i>Leg. 666</i> c ; MOSCH. <i>4, 44,</i> A. TAT. <i>5, 22, etc. ;</i><br><b>   II</b> tout instrument de fer :<br><b>      1</b> épée, IL. <i>18, 34 ; 23, 30 ;</i> OD. <i>16, 294 ;</i><br><b>      2</b> pointe de flèche, IL. <i>4, 123 ;</i><br><b>      3</b> hache, IL. <i>4, 485 ;</i> OD. <i>19, 587 ; 21, 97, 114, 127 ;</i> HÉS. <i>O. 418 ;</i><br><b>      4</b> faux, HÉS. <i>O. 385, 741 ;</i> EUR. <i>Hipp. 76 ; particul</i>. faux à un char de guerre, XÉN. <i>Cyr. 6, 4, 18 ;</i><br><b>      5</b> hameçon, THCR. <i>Idyl. 21, 49 ;</i><br><b>   III</b> marché au fer XÉN. <i>Hell. 3, 3, 7</i>.<br><span><b><span class=\"arrow\"></span></b> ἡ σίδηρος, NIC. <i>Th. 923. Dor</i>. σίδαρος <span>[ᾱ]</span> PD. <i>l. c. etc. Touj. au sg. excepté dans</i> THCR. <i>Idyl. l. c. où le dat. pl</i>. σιδάροις (<i>dor. p</i>. σιδήροις) <i>peut d’ailleurs venir également de</i> σίδηρον.<br><span><b>Étym</b>. <i>inconnue</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σιδηρος - σίδηρος</font>\n<br><br>de dérivation incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G4605":"<h1>Sidon</h1>\n<p>Strong n° 4605 <i>Prononciation [sid-one']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Sidon = « abondance de poisson, pêche »\n<ol><li>une ancienne et riche cité de Phénicie, sur la côte est de la mer Méditerranée, à un peu moins de 30 km au nord de Tyr</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n➀ <b>Σιδών, ῶνος (ἡ)</b> <span>[ῑ]</span> Sidon (<i>auj</i>. Saïda) <i>v. de Phénicie,</i> OD. <i>15, 425 ;</i> HDT. <i>2, 116, etc. ;</i> XÉN. <i>Ages. 2, 30, etc</i>.<br><br>\n➁ <b>Σιδών, όνος (ὁ)</b> <span>[ῑ <i>par nécess. prosod</i>.]</span> habitant de Sidon, IL. <i>23, 743</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Σιδων</font> &lt; צידון - <font face=\"Georgia\">Σιδών</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n11 fois dans 11 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Marc (3)</li>\n<li>Luc (4)</li>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4606":"<h1>Sidonios</h1>\n<p>Strong n° 4606 <i>Prononciation [sid-o'-nee-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un habitant de Sidon, un Sidonien</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n➀ <b>Σιδώνιος, α, ον</b> <span>[σῑ]</span> de Sidon, Sidonien, HDT. <i>7, 89 ; 8, 67, etc. ;</i> SOPH. <i>fr. 756 Dind. etc</i>.<br><span><b>Étym</b>. Σιδών.</span><br><br>\n➁ <b>Σιδώνιος, ου (ὁ)</b> Sidônios, <i>sophiste,</i> LUC. <i>Demon. 14</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Σιδωνιος - Σιδώνιος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4607":"<h1>sikarios</h1>\n<p>Strong n° 4607 <i>Prononciation [sik-ar'-ee-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un assassin\n<ol type=\"a\">\n<li>celui qui porte une dague ou courte épée sous son manteau, ce qui lui permet de tuer en secret sa victime</li>\n<li>un coupe-jarret</li>\n</ol>\n</li>\n<li>sicaire, fanatique, juif antiromain, zélote</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σικάριος, ου (ὁ)</b> = <i>lat</i>. sicarius, sicaire, assassin, JOS. <i>A.J. 20, 8, 10 ;</i> NT. <i>Ap. 21, 38</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σικαριος - σικάριος</font>\n<br><br>origine : Latin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td> n'importe quel « meurtrier », – dont le mot , « brigand, assassin », est un des types ; tandis que  dans le NT contient une certaine emphase.</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4608":"<h1>sikera</h1>\n<p>Strong n° 4608 <i>Prononciation [sik'-er-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>boisson forte, breuvage qui intoxique, différent du vin; c'était un produit artificiel, fait d'un mélange d'ingrédients, dérivés soit de grains ou légumes, ou de jus de fruits (dattes), ou d'une décoction de miel</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σίκερα</b>, <i>indécl. ou</i> <b>σίκερα, -ερος (τὸ)</b> boisson fermentée (cidre, <i>etc</i>.) SPT. <i>Lev. 10, 9 ; Esaï. 24, 9 ;</i> NT. <i>Luc. 1, 15 ; p. ext. en parl. du vin,</i> SPT. <i>Num. 28, 7</i>.<br><span><b>Étym</b>. <i>hébr</i>. schêkâr.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σικερα - σίκερα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G4609":"<h1>Silas</h1>\n<p>Strong n° 4609 <i>Prononciation [see'-las]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Silas = « de la forêt, demandé »\n<ol><li>un citoyen Romain, le compagnon de l'apôtre Paul dans plusieurs de ses voyages missionnaires</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Σιλας - Σιλᾶς</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n13 fois dans 13 versets de 1 livre biblique (NT)\n<ul>\n<li>Actes (13)</li>\n</ul>\n</td></tr>\n</table>","G4610":"<h1>Silouanos</h1>\n<p>Strong n° 4610 <i>Prononciation [sil-oo-an-os']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Silvain (Silas) (Angl. Silvanus) = « de la forêt »\n<ol><li>un citoyen Romain, le compagnon de l'apôtre Paul dans plusieurs de ses voyages missionnaires.( Même personne que Silas). Silvain, forme latine de Silas</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Σιλουανός, οῦ (ὁ)</b> = <i>lat</i>. Silvanus, <i>c</i>. Αἰγίπαν, ARIST. MIL. (PLUT. <i>Parall. min. 22</i>).\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Σιλουανος - Σιλουανός</font>\n<br><br>origine : Latin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 4 livres bibliques (NT)\n<ul>\n<li>2 Corinthiens (1)</li>\n<li>1 Thessaloniciens (1)</li>\n<li>2 Thessaloniciens (1)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G4611":"<h1>Siloam</h1>\n<p>Strong n° 4611 <i>Prononciation [sil-o-am']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Siloé (Angl. Siloam) = « envoyé »\n<ol>\n<li>le Bassin de Siloé, une source d'eau dans Jérusalem</li>\n<li>la Tour de Siloé, qui peut être une tour proche ou sur le Bassin de Siloé, qui en s'écroulant a tué 18 hommes; très vraisemblablement, ils étaient entrain de se purifier.</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Σιλωαμ</font> &lt; שלח - <font face=\"Georgia\">Σιλωάμ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Jean (2)</li>\n</ul>\n</td></tr>\n</table>","G4612":"<h1>simikinthion</h1>\n<p>Strong n° 4612 <i>Prononciation [sim-ee-kin'-thee-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un tablier étroit, ou linge qui recouvrait, porté par les travailleurs et les serviteurs ou bien mouchoir (sens discuté)</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σιμικινθιον - σιμικίνθιον</font>\n<br><br>origine : Latin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4613":"<h1>Simon</h1>\n<p>Strong n° 4613 <i>Prononciation [see'-mone]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Simon = « qui écoute, qui entend »\n<ol>\n<li>Simon Pierre était l'un des apôtres</li>\n<li>Simon le Zélote, un des apôtres</li>\n<li>Simon, père de Judas qui trahit Jésus.</li>\n<li>Simon le Mage, le sorcier samaritain</li>\n<li>Simon le corroyeur de Joppé (<a class=\"ref\" data-r=\"ACT10\">Actes 10</a>)</li>\n<li>Simon le Pharisien (<a class=\"ref\" data-r=\"LUK7.40-44\">Luc 7.40-44</a>)</li>\n<li>Simon de Cyrène qui porta la croix de Christ</li>\n<li>Simon cousin de Jésus, fils de Cléopas</li>\n<li>Simon le lépreux, de Béthanie, sans doute apparenté à Lazare</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Σίμων, ωνος (ὁ)</b> <span>[ῑ]</span><br><b>      1</b> Simon, <i>h</i>. AR. <i>Nub. 351, 399 ; Eq. 242 ;</i> XÉN. <i>Eq. 1, 1, etc. ;</i><br><b>      2</b> coup au jeu de dés, EUB. <i>3, 232 Meineke</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Σιμων</font> &lt; שמעון - <font face=\"Georgia\">Σίμων</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n75 fois dans 70 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (9)</li>\n<li>Marc (10)</li>\n<li>Luc (17)</li>\n<li>Jean (26)</li>\n<li>Actes (13)</li>\n</ul>\n</td></tr>\n</table>","G4614":"<h1>Sina</h1>\n<p>Strong n° 4614 <i>Prononciation [see-nah']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Sinaï (Angl. Sinai) = « épineux »\n<ol><li>montagne ou plutôt une région montagneuse, rendue célèbre par la loi donnée à Moïse au mont Horeb. Ce mont se trouverait parmi les hauteurs de la péninsule sinaïtique</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Σινα</font> &lt; סיני - <font face=\"Georgia\">Σινᾶ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 2 livres bibliques (NT)\n<ul>\n<li>Actes (2)</li>\n<li>Galates (2)</li>\n</ul>\n</td></tr>\n</table>","G4615":"<h1>sinapi</h1>\n<p>Strong n° 4615 <i>Prononciation [sin'-ap-ee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>sénevé, le nom d'une plante des régions orientales, qui provenait d'une toute petite graine puis atteignait la hauteur d'un arbre, 3 mètres et plus ; de là une chose insignifiante est comme un grain de sénevé, mais elle peut grandir d'une façon considérable</li>\n<li>rapprocher de sinapisme, de graine de moutarde</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σίναπι, εως (τὸ)</b> <span>[ῐᾱῐ]</span> sénevé, <i>d’où</i> moutarde, ANAXIPP. (<i>Com. fr. 4, 460</i>) ; NT. <i>Matth. 13, 31 ; Marc. 4, 31, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Les Att. emploient de préférence</i> νᾶπυ, <i>v</i>. ATH. <i>367</i> a.<br><span><b>Étym</b>. <i>pré-grec ; cf</i>. σίναπυ, σίνηπι, σίνηπυ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σιναπι - σίναπι</font>\n<br><br>vient peut-être de sinomai (faire mal, c.à.d. cuire)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Marc (1)</li>\n<li>Luc (2)</li>\n</ul>\n</td></tr>\n</table>","G4616":"<h1>sindon</h1>\n<p>Strong n° 4616 <i>Prononciation [sin-done']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>étoffe de lin, spéc. la plus fine et coûteuse, dans laquelle était enveloppé le corps d'un mort, un linceul, un suaire</li>\n<li>chose faite de fin tissu\n<ol type=\"a\">\n<li>d'un léger et ample vêtement porté la nuit sur un corps dénudé</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σινδών, όνος (ἡ) :<br>   I</b> fin tissu de lin à l’usage des Indiens, HDT. <i>1, 200 ; 2, 95 ;</i> THC. <i>2, 49 ;</i> STR. <i>693, 717, etc. ; p. anal. :</i><br><b>      1</b> tissu de laine fine, TH. <i>H.P. 4, 7, 7 ;</i><br><b>      2</b> sorte de mousseline, HDT. <i>2, 86 ; 7, 181 ;</i><br><b>   II</b> objet fait de cette étoffe de lin :<br><b>      1</b> robe légère, LUC. <i>C. deor. 10 ;</i><br><b>      2</b> voile, SOPH. <i>Ant. 1222 ;</i><br><b>      3</b> voile de navire, EUR. <i>fr. 775, 36 ;</i> ANTH. <i>11, 404 ;</i> ALCIPHR. <i>1, 12, etc. ;</i><br><b>      4</b> drapeau, POL. <i>2, 66, 10, etc</i>.<br><span><b>Étym</b>. Ἰνδός, <i>propr</i>. tissu de l’Inde.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σινδων - σινδών</font>\n<br><br>origine incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 5 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (4)</li>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G4617":"<h1>siniazo</h1>\n<p>Strong n° 4617 <i>Prononciation [sin-ee-ad'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>cribler, secouer dans un tamis</li>\n<li>fig. par agitation interne, essayer de renverser la foi de quelqu'un</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σινιάζω</b>, passer au crible, trier, NT. <i>Luc. 22, 31</i>.<br><span><b>Étym</b>. σινίον, crible, ECCL. <i>de</i> σίνος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σινιαζω - σινιάζω</font>\n<br><br>vient de sinion (un tamis)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G4618":"<h1>siteutos</h1>\n<p>Strong n° 4618 <i>Prononciation [sit-yoo-ros']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>engraissé, gras</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σιτευτός, ή, όν</b> <span>[ῑ]</span> engraissé, <i>en parl. d’animaux,</i> EPIGEN. <i>3, 537 Meineke ;</i> POL. <i>39, 2, 7, etc. ; en parl. d’enfants,</i> XÉN. <i>An. 5, 4, 32</i>.<br><span><b>Étym</b>. <i>vb. de</i> σιτεύω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σιτευτος - σιτευτός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 1 livre biblique (NT)\n<ul>\n<li>Luc (3)</li>\n</ul>\n</td></tr>\n</table>","G4619":"<h1>sitistos</h1>\n<p>Strong n° 4619 <i>Prononciation [sit-is-tos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>engraissé, bien nourri, gras</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σιτιστός, ή, όν</b> <span>[σῑ]</span> engraissé, <i>en parl. des volatiles,</i> ATH. <i>656</i> e ; NT. <i>Matth. 22, 4 ;</i> JOS. <i>A.J. 8, 2, 4</i>.<br><span><b>Étym</b>. σιτίζω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σιτιστος - σιτιστός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Matthieu (1)</li>\n</ul>\n</td></tr>\n</table>","G4620":"<h1>sitometron</h1>\n<p>Strong n° 4620 <i>Prononciation [sit-om'-et-ron]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>une 'portion' mesurée de grain ou 'nourriture'</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σιτομέτριον, ου (τὸ)</b> <span>[σῑ]</span> <i>c</i>. σιτόμετρον NT. <i>Luc. 12, 42</i>.<br><br>\n<b>σιτό·μετρον, ου (τὸ)</b> <span>[ῑ]</span> <i>c</i>. σιτομετρία, PLUT. <i>M. 313</i> b.<br><span><b>Étym</b>. σῖτος, μέτρον.</span><br><br>\n<b>σιτομετρία, ας (ἡ)</b> <span>[σῑ]</span><br><b>      1</b> charge <i>de</i> σιτομέτρης, PLUT. <i>Cato ma. 8 ;</i><br><b>      2</b> provision <i>ou</i> distribution de blé <i>ou</i> de vivres, DS. <i>2, 41</i>.<br><span><b>Étym</b>. σιτομέτρης.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σιτομετριον - σιτομέτριον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G4621":"<h1>sitos</h1>\n<p>Strong n° 4621 <i>Prononciation [see'-tos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>blé, grain</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σῖτος, ου (ὁ) :<br>   I</b> blé :<br><b>      1</b> <i>dans l’état naturel,</i> OD. <i>13, 244 ;</i> HDT. <i>1, 22 ; 4, 17, etc. ;</i> THC. <i>2, 19 ; 3, 1 ; 4, 1 et 2, etc. ;</i> XÉN. <i>An. 5, 4, 27, etc. ;</i> σῖτον ποιεῖν, DÉM. <i>1048, 23,</i> cultiver le blé (<i>mais v. ci-dessous) ; p. suite :</i> blé moulu, farine, <i>d’où</i> pain (<i>p. opp. à la viande</i>) OD. <i>9, 9 ; 12, 19 ;</i> σῖτον ἔδειν, OD. <i>8, 222 ; 9, 90 ; 10, 101 ; ou</i> ἐσθίειν, HÉS. <i>O. 148,</i> manger du pain ; <i>p. opp. à</i> ὄψον, XÉN. <i>Mem. 3, 14, 2 ;</i> σῖτος μεμαγμένος, THC. <i>4, 16,</i> farine pétrie, <i>càd</i>. pain ; σῖτος ὀπτός, HDT. <i>2, 168,</i> farine cuite, <i>càd</i>. pain ; σῖτον ποιεῖν (<i>v. ci-dessus</i>) XÉN. <i>Cyr. 4, 5, 1, etc</i>. faire du pain ;<br><b>      2</b> aliments solides <i>en gén., p. opp. à la boisson, à</i> ποτή, IL. <i>19, 306 ;</i> OD. <i>9, 87 ; 10, 58 ; à</i> οἶνος, IL. <i>9, 706, etc. ;</i> OD. <i>3, 479, etc. ; à</i> μέθυ, OD. <i>4, 746, etc. ; au plur</i>. σῖτα, <i>p. opp. à</i> ποτά, HDT. <i>5, 34, 65, etc. ; p. suite,</i> nourriture, alimentation <i>pour les hommes,</i> IL. <i>10, 163 ;</i> OD. <i>16, 83, etc. ;</i> σῖτον αἱρεῖσθαι, HDT. <i>7, 120, etc</i>. prendre de la nourriture ; <i>cf</i>. THC. <i>2, 75 ;</i> XÉN. <i>Cyr. 4, 2, 41, etc. ; particul</i>. subsistances militaires (<i>cf</i>. σιτηρέσιον) THC. <i>2, 6 ; 4, 26 ; 5, 47 ;</i> XÉN. <i>An. 7, 1, 41 ; pour les animaux, en parl. de fourrage,</i> HÉS. <i>O. 602 ;</i> EUR. <i>H.f. 383 ;</i> XÉN. <i>Cyr. 8, 1, 38, etc. ; fig. en parl. des semences qui sont comme une nourriture pour la terre,</i> XÉN. <i>Œc. 17, 10 ;</i><br><b>      3</b> <i>particul. à Athènes,</i> pension alimentaire : σῖτον διδόναι, DÉM. <i>818, 6, etc</i>. allouer une pension alimentaire ; δίκη σίτου, IS. <i>38, 37,</i> procès pour demande de pension alimentaire ; σίτου δικάσασθαί τινι, DÉM. <i>1362, 27,</i> intenter un procès pour demande de pension alimentaire ;<br><b>      4</b> <i>à Rome,</i> distribution de blé au peuple, ARR. <i>Epict. 1, 10, 2 ;</i><br><b>   II</b> aliments élaborés, résidu des aliments absorbés, excréments, HPC. <i>1143</i> a, <i>1164</i> f, <i>etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Plur. hétérog</i>. τὰ σῖτα, HDT. <i>4, 128 ; 5, 34, etc. ;</i> ATT.<br><span><b>Étym</b>. <i>inconnue</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σιτος - σῖτος</font>\n<br><br>vient de sita (see'-tah), de dérivation incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n14 fois dans 14 versets de 7 livres bibliques (NT)\n<ul>\n<li>Matthieu (4)</li>\n<li>Marc (1)</li>\n<li>Luc (3)</li>\n<li>Jean (1)</li>\n<li>Actes (2)</li>\n<li>1 Corinthiens (1)</li>\n<li>Apocalypse (2)</li>\n</ul>\n</td></tr>\n</table>","G4622":"<h1>Sion</h1>\n<p>Strong n° 4622 <i>Prononciation [see-own']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Sion = « un lieu élevé »\n<ol>\n<li>la colline sur laquelle la plus ancienne partie de Jérusalem fut construite</li>\n<li>souvent utilisé pour désigner toute la ville de Jérusalem</li>\n<li>parce que Jérusalem, lieu du temple, était la demeure de Dieu</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Σιών (ἡ)</b> <span>[ῑ]</span> <i>indécl</i>. Sion, <i>mt. sur laquelle est située Jérusalem, d’où</i> Jérusalem, ANTH. <i>1, 52, etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Σιων</font> &lt; ציון - <font face=\"Georgia\">Σιών</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n7 fois dans 7 versets de 6 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Jean (1)</li>\n<li>Romains (2)</li>\n<li>Hébreux (1)</li>\n<li>1 Pierre (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G4623":"<h1>siopao</h1>\n<p>Strong n° 4623 <i>Prononciation [see-o-pah'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>être silencieux, se tenir en paix\n<ol type=\"a\">\n<li>utilisé pour le silence d'un muet</li>\n</ol>\n</li>\n<li>métaph. une mer calme, tranquille</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σιωπάω-ῶ</b> <span>(<i>impf</i>. ἐσιώπων, <i>f</i>. σιωπήσομαι, <i>postér</i>. σιωπήσω, <i>ao</i>. ἐσιώπησα, <i>pf</i>. σεσιώπηκα ; <i>pass. f</i>. σιωπηθήσομαι, <i>ao</i>. ἐσιωπήθην, <i>pf</i>. σεσιώπημαι)</span><br><b>   I <i>intr.</i></b> garder le silence, se taire, IL. <i>2, 280 ; 23, 568, etc. ;</i> HDT. <i>7, 10 ;</i> ATT. ; πρός τινα, PLAT. <i>Phædr. 234</i> a ; τινι, AR. <i>Lys. 530, etc</i>. auprès de qqn ; πρός τι, XÉN. <i>Cyr. 5, 5, 20 ;</i> ὑπέρ τινος, EUR. (PLUT. <i>M. 1108</i> b) ; περί τινος, ISOCR. <i>218</i> a, à l’égard de qqe ch. ;<br><b>   II <i>tr.</i></b> taire, passer sous silence, <i>acc</i>. EUR. <i>fr. 1024 ;</i> XÉN. <i>Conv. 6, 10, etc. ; au pass</i>. être tu, être passé sous silence, être gardé secret, EUR. <i>Ion 432 ;</i> ISOCR. <i>6</i> e ; ESCHN. <i>75, 37 ;</i> DÉM. <i>354, 20, etc. ;</i><br><b><i>Moy.</i></b> <span>(<i>ao</i>. ἐσιωπησάμην)</span> faire taire, <i>acc</i>. POL. <i>18, 29, 4</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Conjug. dor</i>. σωπάω ; <i>f. en compos</i>. -σωπάσομαι <span>[ᾱ]</span> PD. <i>O. 13, 91 ; part. pf</i>. σεσωπαμένος <span>[ᾱ]</span> PD. <i>I. 1, 63 Bgk</i>.<br><span><b>Étym</b>. σιωπή.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σιωπαω - σιωπάω</font>\n<br><br>vient de 'siope' (silence, chut !, mutisme, tranquillité involontaire, ou incapabilité de parler), et par là diffère de  qui est plutôt un refus volontaire de parler, ou une indisposition dans la parole, mais les deux termes sont souvent utilisés comme des synonymes</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td> – décrit une condition tranquille en général, incluant le silence\n<br><br> – décrit une condition mentale et ses manifestations, spéc. dans le mutisme (silence à cause de crainte, chagrin, terrible anxiété, etc.)\n<br><br> – est le terme le plus physique et externe, il indique l'abstinence de parole</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n11 fois dans 11 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Marc (5)</li>\n<li>Luc (3)</li>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4624":"<h1>skandalizo</h1>\n<p>Strong n° 4624 <i>Prononciation [skan-dal-id’-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>poser une pierre d'achoppement ou un obstacle dans le chemin, sur lequel un autre peut trébucher et tomber, métaph. offenser\n<ol type=\"a\">\n<li>attirer à pécher</li>\n<li>faire qu'une personne commence à se méfier de quelqu'un en qui elle avait l'habitude de croire et d'obéir\n<ol>\n<li>être une occasion de chute</li>\n<li>être offensé dans quelqu'un, c.à.d. voir dans un autre ce que je désapprouve et qui m'empêche de reconnaître son autorité</li>\n<li>faire que quelqu'un juge un autre non favorablement ou injustement</li>\n</ol>\n</li>\n<li>puisque quelqu'un qui trébuche ou dont les pieds s'empêtrent se sent contrarié\n<ol>\n<li>faire que quelqu'un ait du déplaisir à une chose</li>\n<li>rendre indigné</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σκανδαλίζω</b> <span>[δᾰ]</span> causer du scandale, scandaliser, NT. <i>Matth. 5, 29 ; 17, 27, etc. ; au pass</i>. être scandalisé, être offensé, NT. <i>Matth. 11, 6 ; 26, 31 et 33, etc</i>.<br><span><b>Étym</b>. σκανδάλον.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σκανδαλιζω - σκανδαλίζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n30 fois dans 28 versets de 7 livres bibliques (NT)\n<ul>\n<li>Matthieu (14)</li>\n<li>Marc (8)</li>\n<li>Luc (2)</li>\n<li>Jean (2)</li>\n<li>Romains (1)</li>\n<li>1 Corinthiens (2)</li>\n<li>2 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4625":"<h1>skandalon</h1>\n<p>Strong n° 4625 <i>Prononciation [skan’-dal-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>le bâton mobile ou détente d'un piège\n<ol type=\"a\">\n<li>une trappe, un piège</li>\n<li>tout obstacle placé sur le chemin et faisant tomber quelqu'un (une pierre d'achoppement, une occasion de chute) c.à.d. un rocher qui fait trébucher</li>\n<li>fig. appliquée à Jésus Christ, dont la personne et la carrière étaient si contraires aux suppositions des Juifs concernant le Messie, qu'ils l'ont rejeté et par leur obstination ont vu le naufrage de leur salut</li>\n</ol>\n</li>\n<li>toute personne ou chose par laquelle quelqu'un est amené à l'erreur ou au péché</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σκάνδαλον, ου (τὸ)</b> <span>[δᾰ]</span> piège placé sur le chemin, obstacle pour faire tomber, SPT. <i>Jos. 23, 13 ; 1Reg. 18, 21 ;</i> NT. <i>Rom. 11, 9 ; 1Petr. 2, 7 ; fig</i>. scandale, SPT. <i>Lev. 19, 14, etc. ;</i> NT. <i>Matth. 18, 7 ; Luc. 17, 1, etc</i>.<br><span><b>Étym</b>. <i>p.-ê. pré-grec ou emprunt à une autre langue indo-europ</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σκανδαλον - σκάνδαλον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n15 fois dans 13 versets de 8 livres bibliques (NT)\n<ul>\n<li>Matthieu (5)</li>\n<li>Luc (1)</li>\n<li>Romains (4)</li>\n<li>1 Corinthiens (1)</li>\n<li>Galates (1)</li>\n<li>1 Pierre (1)</li>\n<li>1 Jean (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G4626":"<h1>skapto</h1>\n<p>Strong n° 4626 <i>Prononciation [skap'-to]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>creuser, bêcher</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σκάπτω</b> <span>(<i>f</i>. σκάψω, <i>ao</i>. ἔσκαψα, <i>pf. inus. ; pass. ao.2</i> ἐσκάφην, <i>pf</i>. ἔσκαμμαι)</span> creuser, HPC. <i>Art. 789 ;</i> PLAT. <i>Leg. 778</i> e ; <i>joint à</i> μοχθεῖν, AR. <i>Pl. 525, etc. ;</i> τὰ ἐσκαμμένα, fossé <i>ou</i> ligne creusée dans le sol comme limite aux sauteurs du pentathle, <i>d’où prov. :</i> <span>ὑπὲρ τὰ ἐσκαμμένα ἅλλεσθαι</span>, PLAT. <i>Crat. 413</i> a, sauter par-dessus la limite, franchir les bornes ; <i>particul</i>. creuser le sol pour ensemencer, <i>etc</i>. XÉN. <i>Œc. 16, 15 ; ou</i> pour planter, DS. <i>4, 31 ;</i> διὰ βοῶν σκάπτειν, GEOP. <i>2, 24,</i> creuser à l’aide de bœufs, <i>càd</i>. labourer ; <i>particul</i>. fouiller la terre autour d’une plante, sarcler, HH. <i>Merc. 90 ;</i> XÉN. <i>Œc. 20, 20 ;</i><br><b><i>Moy.</i></b> (<i>seul. prés</i>.) creuser, fouir pour soi, PHOCYL. <i>158</i>.<br><span><b>Étym</b>. <i>p.-ê. emprunt à un substrat pré-grec et/ou pré-indo-europ. ; cf</i>. σκάφος, σκάφη, κάπετος, σκαπάνη.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σκαπτω - σκάπτω</font>\n<br><br>apparemment un verbe primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 1 livre biblique (NT)\n<ul>\n<li>Luc (3)</li>\n</ul>\n</td></tr>\n</table>","G4627":"<h1>skaphe</h1>\n<p>Strong n° 4627 <i>Prononciation [skaf'-ay]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>toute chose creusée, un vase creux, une auge, un plateau, une baignoire</li>\n<li>d'un bateau</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n➀ <b>σκαφή, ῆς (ἡ)</b> <span>[ᾰ]</span><br><b>      1</b> action de fouir, PROCL. <i>Hes. O. 569 ;</i><br><b>      2</b> <i>c</i>. κατασκαφή, APP. <i>Lib. 136</i>.<br><span><b>Étym</b>. σκάπτω.</span><br><br>\n➁ <b>σκάφη, ης (ἡ)</b> <span>[ᾰ]</span> tout corps creusé, <i>d’où :</i><br><b>   I</b> bassin en terre <i>ou</i> en bois, <i>particul. :</i><br><b>      1</b> auge, HDT. <i>4, 73 ;</i> AR. <i>Eccl. 742, etc. ;</i><br><b>      2</b> huche à cuire, pétrin, TIMOCL. <i>et</i> PHILÉM. (<i>Com. fr. 3, 612 et 4, 7</i>) ;<br><b>      3</b> baignoire, HPC. <i>684, 53 ;</i><br><b>      4</b> cuvette, ESCHL. <i>fr. 210 ;</i><br><b>      5</b> crachoir, AR. <i>fr. 154 ;</i><br><b>      6</b> vase pour les sacrifices, AR. <i>Eccl. 742 ;</i> MÉN. <i>4, 312 Meineke ;</i><br><b>   II</b> sorte de corbeille pour exposer les enfants, SOPH. <i>fr. 574 ;</i> ARSTT. <i>Poet. 16, 3 ;</i> PLUT. <i>Rom. 3 ;</i><br><b>   III</b> canot, barque, SOPH. <i>fr. 574, 576 ;</i> AR. <i>Eq. 1315 ;</i> POL. <i>1, 23, 7 ;</i><br><b>   IV</b> sorte de bandeau de tête, GAL. <i>12, 468</i>.<br><span><b>Étym</b>. σκάπτω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σκαφη - σκάφη</font>\n<br><br>un mot primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 1 livre biblique (NT)\n<ul>\n<li>Actes (3)</li>\n</ul>\n</td></tr>\n</table>","G4628":"<h1>skelos</h1>\n<p>Strong n° 4628 <i>Prononciation [skel'-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>la jambe, qui va de la hanche aux orteils</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σκέλος, εος-ους (τὸ)</b> jambe de l’homme et des animaux, IL. <i>16, 314 (seul ex. dans Hom</i>.) ; ESCHL. <i>Eum. 37, Pr. 14 ;</i> SOPH. <i>El. 753 ;</i> HDT. <i>3, 103 ; 7, 61, etc. ;</i> PLAT. <i>Conv. 190</i> d, <i>etc. ;</i> κατὰ σκέλος βαδίζειν, ARSTT. <i>H.A. 2, 1, 15, etc</i>. marcher pas à pas, <i>en parl. de certains animaux (lion, chameau, etc.) qui déplacent à la fois une jambe de derrière et une de devant (aller l’amble) ;</i> ἐπὶ σκέλος πάλιν χωρεῖν, EUR. <i>Ph. 1400 ; ou</i> ἀνάγειν, AR. <i>Av. 383 ;</i> aller pas à pas, à reculons ; παρὰ σκέλος ἀπαντᾷ, ARR. <i>Epict. 2, 12, 1,</i> l’affaire tourne à rebours, <i>càd</i>. autrement qu’on ne voudrait ; <i>fig</i>. τὰ σκέλη :<br><b>      1</b> jambages d’une machine, ORIB. <i>122 Mai ; ou</i> d’une échelle, HÉRON, PHIL. BYZ. ;<br><b>      2</b> bouts pendants d’une bandelette, ORIB. <i>92 Mai ;</i><br><b>      3</b> parties symétriques d’un discours, SCH.-ESCHL. <i>Sept. 94 ;</i><br><b>      4</b> τὰ μακρὰ σκέλη, DS. <i>13, 107 ;</i> PLUT. <i>Lys. 14 ;</i> APP. <i>Mithr. 30 ; ou simplement</i> τὰ σκέλη, STR. <i>395 ;</i> PLUT. <i>Cim. 13 ; ou</i> τὰ Πειραϊκὰ σκέλη, ANTH. <i>7, 406,</i> les Longs murs <i>entre Athènes et le Pirée ;</i> τὰ σκέλη, les Murs <i>entre Mégare et Nisæa,</i> AR. <i>Lys. 1172</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Duel nom.-acc</i>. σκέλη, AR. <i>Pax 325, 820 ; dans une inscr. att. nom.-acc. duel</i> σκέλει δύο, CIA. <i>2, 652, a, 24 (398 av. J.C</i>.) ; <i>v. Meisterh. p. 103, § 51, 6</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *skel-, courber ; <i>cf</i>. σκολιός, <i>lat</i>. scelus, <i>all</i>. scheel.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σκελος - σκέλος</font>\n<br><br>vient apparemment de skello (dessécher, à travers l'idée de maigreur)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 1 livre biblique (NT)\n<ul>\n<li>Jean (3)</li>\n</ul>\n</td></tr>\n</table>","G4629":"<h1>skepasma</h1>\n<p>Strong n° 4629 <i>Prononciation [skep'-as-mah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>une couverture, spéc. des vêtements</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σκέπασμα, ατος (τὸ)</b> abri, couverture, PLAT. <i>Pol. 276</i> d ; <i>en parl. de vêtements,</i> ARSTT. <i>Pol. 7, 13, 3 ; de chaussures,</i> PLAT. <i>Leg. 942</i> d ; <i>des ongles qui protègent l’extrémité des doigts,</i> ARSTT. <i>P.A. 4, 10, 28 ; des cils,</i> ARSTT. <i>G.A. 5, 1 ; en gén. de tout ce qui protège en couvrant,</i> ARSTT. <i>Metaph. 7, p. 168, 11 ; An. 1, 1, etc</i>.<br><span><b>Étym</b>. σκεπάζω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σκεπασμα - σκέπασμα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G4630":"<h1>Skeuas</h1>\n<p>Strong n° 4630 <i>Prononciation [skyoo-as']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Scéva (Angl. Sceva) = « lecteur de l'esprit », « disposé »\n<ol><li>un des principaux sacrificateurs résidant à Ephèse</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Σκευᾶς, ᾶ (ὁ)</b> = Scæva, <i>n. d’h. rom</i>. PLUT. <i>Cæs. 16, etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Σκευας - Σκευᾶς</font>\n<br><br>apparemment origine : Latin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4631":"<h1>skeue</h1>\n<p>Strong n° 4631 <i>Prononciation [skyoo-ay']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>tout appareil, équipement, ou fournitures\n<ol type=\"a\">\n<li>des accessoires ou agrès d'un navire</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σκευή, ῆς (ἡ)</b> appareil, <i>d’où :</i><br><b>      1</b> vêtement, <i>en gén</i>. HDT. <i>7, 15 ;</i> SOPH. <i>O.C. 555 ;</i> PLAT. <i>Crit. 53</i> d, <i>etc. ; particul</i>. costume (d’acteur, HDT. <i>1, 24 ;</i> du chœur, LYS. <i>162, 2 ;</i> de prêtre <i>ou</i> de magistrat, AND. <i>15, 10 ;</i> costume étranger, THC. <i>1, 130, etc</i>.) ; équipement militaire, THC. <i>3, 94 ;</i> harnachement de cheval, THC. <i>6, 94, etc. ;</i> équipement d’un navire, DS. <i>14, 79 ;</i> NT. <i>Ap. 27, 19, etc. ;</i><br><b>      2</b> façon d’être d’un vêtement, mode, air, aspect, HDT. <i>7, 62 et 66 ;</i> THC. <i>1, 6, etc. ;</i><br><b>      3</b> <i>c</i>. αἰδοῖον, ANTH. <i>5, 242</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dor</i>. σκευά <span>[ᾱ]</span>.<br><span><b>Étym</b>. σκεῦος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σκευη - σκευή</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4632":"<h1>skeuos</h1>\n<p>Strong n° 4632 <i>Prononciation [skyoo'-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un vase</li>\n<li>un outil\n<ol type=\"a\">\n<li>au pluriel\n<ol>\n<li>ustensiles de cuisine, appareils domestiques</li>\n<li>les agrès et l'armement de vaisseaux, utilisé en particulier pour les voiles et cordages</li>\n</ol>\n</li>\n</ol>\n</li>\n<li>métaph.\n<ol type=\"a\">\n<li>un homme de qualité, un instrument choisi</li>\n<li>dans un mauvais sens, un assistant dans l'accomplissement de mauvaises actions</li>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σκεῦος, εος-ους (τὸ)</b> tout objet d’équipement (meuble, outil, instrument, arme, agrès, harnais, <i>etc.) ; d’ord. au pl</i>. THC. <i>2, 13 ;</i> XÉN. <i>An. 7, 4, 18 ; Œc. 8, 11, 12, etc. ;</i> PLAT. <i>Rsp. 373</i> a, <i>Leg. 679</i> a, <i>etc. ; rar. au sg</i>. THC. <i>4, 128 ;</i> AR. <i>Th. 402 ; particul. en parl. d’une armée :</i> τὰ σκεύη, l’équipement des hommes, THC. <i>6, 31, etc. ; ou</i> des chevaux, XÉN. <i>Cyr. 4, 5, 55 ; ou</i> les bagages <i>en gén</i>. XÉN. <i>Mem. 3, 13, 6 ; Hell. 5, 4, 17, etc. ; t. de droit :</i> tout objet mobilier, LYS. <i>154, 35 ; fig</i>. toute personne <i>ou</i> toute chose inerte, <i>particul. :</i><br><b>      1</b> le corps (<i>p. opp. à l’âme</i>) NT. <i>2Cor. 4, 7 ; 1Thess. 4, 4 ; 1Petr. 3, 7 ;</i><br><b>      2</b> homme qui est l’instrument <i>ou</i> le complaisant d’un autre, POL. <i>13, 5, 7 ; particul. en parl. d’une créature choisie par Dieu,</i> vase d’élection, NT. <i>Ap. 9, 15 ;</i><br><b>      3</b> <i>p. anal</i>. nom neutre (<i>d’ord</i>. τὰ μεταξὺ ὀνόματα) PROTAG. (ARSTT. <i>Soph. el. 14, 4 ; Rhet. 3, 5, 5</i>) ;<br><b>      4</b> <i>c</i>. αἰδοῖον, EL. <i>N.A. 17, 11 ;</i> A. PL. <i>243</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Duel nom.-acc</i>. σκεύη, AR. <i>Eq. 983</i>.<br><span><b>Étym</b>. <i>inconnue ; cf</i>. σκευή.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σκευος - σκεῦος</font>\n<br><br>affinité incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n23 fois dans 22 versets de 12 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (2)</li>\n<li>Luc (2)</li>\n<li>Jean (1)</li>\n<li>Actes (5)</li>\n<li>Romains (3)</li>\n<li>2 Corinthiens (1)</li>\n<li>1 Thessaloniciens (1)</li>\n<li>2 Timothée (2)</li>\n<li>Hébreux (1)</li>\n<li>1 Pierre (1)</li>\n<li>Apocalypse (3)</li>\n</ul>\n</td></tr>\n</table>","G4633":"<h1>skene</h1>\n<p>Strong n° 4633 <i>Prononciation [skay-nay']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>tente, tabernacle, (de branches vertes, ou de peaux ou d'autres matériaux)</li>\n<li>de ce bien connu temple de Dieu transportable d'après le modèle duquel fut construit le temple de Jérusalem</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σκηνή, ῆς (ἡ) :<br>   I</b> toute baraque <i>ou</i> construction légère pour servir d’abri, <i>particul. :</i><br><b>      1</b> cabane, hutte, ESCHL. <i>Eum. 656 ;</i><br><b>      2</b> tente : ὑπὸ σκηναῖσιν, SOPH. <i>Aj. 754,</i> sous les tentes ; σκηνὴν ποιεῖν, THC. <i>2, 34 ;</i> ἵστασθαι, XÉN. <i>Cyr. 8, 5, 3,</i> construire, dresser une tente ; τὰς σκηνὰς καταλύειν, POL. <i>6, 40, 2 ; ou</i> διαλύειν, PAUS. <i>10, 25, 3,</i> lever les tentes ; <i>au pl</i>. campement, camp, ESCHL. <i>Eum. 686 ;</i> σκηναὶ ναυτικαί, SOPH. <i>Aj. 3,</i> campement <i>ou</i> quartiers des marins ; <i>chez les Juifs,</i> tente, tabernacle, SPT. <i>2Macc. 10, 6 ;</i> PHIL. <i>2, 297 ;</i> PLUT. <i>M. 671</i> d ; ἑορτὴ σκηνῶν, SPT. <i>Lev. 23, 34,</i> la fête des Tabernacles ; <i>p. ext</i>. repas donné sous la tente, XÉN. <i>Cyr. 2, 3, 1 ; 4, 2, 34, etc. ; en gén</i>. résidence, habitation, maison, temple, EUR. <i>Hec. 1289, Ion 806 ;</i> LUC. <i>Ic. 21 ;</i><br><b>      3</b> boutique, échoppe, AR. <i>Th. 658 ;</i> DÉM. <i>284, 24 ;</i><br><b>      4</b> voiture couverte, <i>sorte de tente portative,</i> ESCHL. <i>Pers. 971 ;</i><br><b>      5</b> <i>très souv</i>. construction en bois et couverte où l’on jouait les pièces de théâtre, <i>d’où</i> scène, <i>et particul</i>. la partie de la scène où jouaient les acteurs, <i>p. opp. à la</i> θυμέλη <i>où évoluait le chœur,</i> AR. <i>Pax 731 ;</i> PLAT. <i>Leg. 817</i> c ; οἱ ἐπὶ σκηνῆς, LUC. <i>Nec. 16 ;</i> ALCIPHR. <i>3, 65 ;</i> οἱ περὶ σκηνήν, PLUT. <i>Galb. 16 ;</i> οἱ ἀπὸ σκηνῆς, DÉM. <i>288, 18,</i> les acteurs (<i>p. opp. à</i> θυμελικοί, acteurs composant le chœur) ; τὰ ἀπὸ σκηνῆς, les choses de théâtre, HDN <i>5, 7, 12, ou (s.-e</i>. μέλη) airs chantés par les acteurs eux-mêmes (sans intervention du chœur) ARSTT. <i>Poet. 24, 6 ; 25, 4 ; Probl. 19, 15 ;</i> τραγικὴ σκηνή, XÉN. <i>Cyr. 6, 1, 54,</i> sorte de construction élevée pour la représentation des tragédies ; <i>p. ext</i>. fiction de théâtre, <i>d’où</i> fiction, mensonge, ANTH. <i>10, 72 ;</i> JOS. <i>B.J. 2, 21, 2 ;</i> HDN <i>3, 12, 7 ;</i> HLD. <i>5, 6, etc. ;</i><br><b>   II</b> <i>p. ext</i>. toute construction servant de couverture :<br><b>      1</b> tenture <i>ou</i> banne de voiture, XÉN. <i>Cyr. 6, 4, 11 ;</i> DS. <i>20, 25 ;</i> PLUT. <i>Them. 26, etc. ;</i><br><b>      2</b> ciel de lit, baldaquin, DÉM. <i>1031, 10</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dor</i>. σκανά <span>[ᾱᾱ]</span>.<br><span><b>Étym</b>. <i>incert</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σκηνη - σκηνή</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n20 fois dans 20 versets de 6 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Luc (2)</li>\n<li>Actes (3)</li>\n<li>Hébreux (10)</li>\n<li>Apocalypse (3)</li>\n</ul>\n</td></tr>\n</table>","G4634":"<h1>skenopegia</h1>\n<p>Strong n° 4634 <i>Prononciation [skay-nop-ayg-ee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>la construction d'un tabernacle</li>\n<li>la fête des Tabernacles ; la dernière des 3 grandes fêtes annuelles auxquelles tout Israélite devait assister, dans le lieu que Dieu avait choisi. Cette fête emprunta son nom à la coutume de séjourner dans des cabanes de feuillage pendant sa célébration. Cette fête se déroulait le 7ème mois de l'année religieuse (Tisri, soit octobre) quand les récoltes et vendanges étaient terminées. Elle devait rappeler le séjour au désert, passé sous des tentes. La fête qui commençait le 15 du mois, durait 7 jours De nombreux holocaustes étaient offerts.</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σκηνο·πηγία, ας (ἡ) :<br>      1</b> action de dresser une tente, <i>d’où</i> construction d’un nid, ARSTT. <i>H.A. 9, 7, 1 ;</i><br><b>      2</b> fête des Tabernacles, <i>chez les Juifs,</i> SPT. <i>Deut. 16, 16 ; 31, 10 ; 2 Macc. 1, 9 ;</i> NT. <i>Joh. 7, 2, etc</i>.<br><span><b>Étym</b>. <i>cf</i>. σκηνοπηγέω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σκηνοπηγια - σκηνοπηγία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G4635":"<h1>skenopoios</h1>\n<p>Strong n° 4635 <i>Prononciation [skay-nop-oy-os']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un fabricant de tente</li>\n<li>quelqu'un qui fait de petites tentes portables, de cuir ou de poils de chèvres, ou de lin, à l'usage des voyageurs</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σκηνο·ποιός, ός, όν :<br>   I</b> <i>adj</i>. qui construit des tentes, des abris, des couvertures, <i>en parl. de la nature,</i> STOB. <i>Ecl. phys. 1, 52, p. 1084 ;</i><br><b>   II</b> <i>subst. :</i><br><b>      1</b> constructeur de tentes, NT. <i>Ap. 18, 3 ;</i><br><b>      2</b> machiniste, mécanicien, ANON. (<i>Com. fr. 4, 680</i>).<br><span><b>Étym</b>. σκηνή, ποιέω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σκηνοποιος - σκηνοποιός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4636":"<h1>skenos</h1>\n<p>Strong n° 4636 <i>Prononciation [skay'-nos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un tabernacle, une tente</li>\n<li>métaph. du corps humain, dans lequel demeure l'âme comme dans une tente, et qui s'écroule le jour de la mort</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σκήνος, εος-ους (τὸ)</b> tente, <i>fig. càd. :</i><br><b>      1</b> le corps, enveloppe de l’âme, HPC. <i>269, 22 ; 916</i> a ; THÉAGÈS (STOB. <i>133, 40</i>) ; PLAT. <i>Ax. 366</i> a ; T. LOCR. <i>100</i> a, <i>101 c et e ;</i> NT. <i>2Cor. 5, 1 ;</i><br><b>      2</b> <i>p. ext</i>. corps d’insecte, ANTH. <i>9, 404 ;</i><br><b>      3</b> corps mort, cadavre, NIC. <i>Al. 447, Th. 742 ;</i> EL. <i>N.A. 5, 3</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dor</i>. σκᾶνος, T. LOCR. <i>ll. cc</i>.<br><span><b>Étym</b>. σκηνή.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σκηνος - σκῆνος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>2 Corinthiens (2)</li>\n</ul>\n</td></tr>\n</table>","G4637":"<h1>skenoo</h1>\n<p>Strong n° 4637 <i>Prononciation [skay-no'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>fixer sa tente, avoir son tabernacle, demeurer (ou vivre) dans un tabernacle (ou tente), tabernacler</li>\n<li>habiter</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σκηνόω-ῶ</b> <span>(<i>f</i>. ώσω, <i>ao</i>. ἐσκήνωσα, <i>pf. pass</i>. ἐσκήνωμαι)</span><br><b>   I <i>tr.</i></b> dresser une tente : σκηνάς, POLYEN <i>7, 21, 6,</i> dresser des tentes ; <i>fig</i>. ἐρείπια, PLUT. <i>Cam. 31,</i> s’établir dans des ruines ;<br><b>   II <i>intr. :</i><br>      1</b> planter des tentes, camper, XÉN. <i>An. 2, 4, 14 ; 7, 4, 11 ;</i><br><b>      2</b> vivre sous une tente, XÉN. <i>Cyr. 2, 1, 25 ;</i><br><b>      3</b> <i>en gén</i>. prendre ses quartiers : κατὰ κώμας, XÉN. <i>An. 4, 5, 23,</i> dans des villages ; ἐν οἰκίαις, XÉN. <i>An. 5, 5, 11,</i> dans des habitations ;<br><b>      4</b> <i>p. ext</i>. habiter, résider, <i>avec</i> ἐν <i>et le dat</i>. XÉN. <i>Hell. 5, 4, 56 ;</i><br><b><i>Moy.</i></b> dresser sa tente, <i>d’où</i> s’établir : πόρρω ἐσκήνωται τοῦ <i>et l’inf</i>. PLAT. <i>Rsp. 610</i> e, elle est loin de, <i>etc</i>.<br><span><b>Étym</b>. σκηνή.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σκηνοω - σκηνόω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 2 livres bibliques (NT)\n<ul>\n<li>Jean (1)</li>\n<li>Apocalypse (4)</li>\n</ul>\n</td></tr>\n</table>","G4638":"<h1>skenoma</h1>\n<p>Strong n° 4638 <i>Prononciation [skay'-no-mah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une tente, un tabernacle\n<ol type=\"a\">\n<li>du temple comme habitation de Dieu</li>\n<li>du tabernacle de l'alliance</li>\n<li>métaph. du corps humain qui est la demeure de l'âme</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σκήνωμα, ατος (τὸ) :<br>   I</b> habitation, maison, tente, <i>au plur</i>. EUR. <i>Hec. 616, Ion 1133, etc. ;</i> XÉN. <i>An. 2, 2, 17 ; Hell. 7, 4, 32, etc. ; particul. :</i><br><b>      1</b> campement de soldats, XÉN. <i>An. 7, 4, 16 ;</i><br><b>      2</b> temple, PAUS. <i>3, 17, 6 ;</i> SPT. <i>Ps. 14, 1 ; 42, 3 ;</i><br><b>   II</b> <i>fig</i>. le corps, NT. <i>2Petr. 1, 13 et 14</i>.<br><span><b>Étym</b>. σκηνόω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σκηνωμα - σκήνωμα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>2 Pierre (2)</li>\n</ul>\n</td></tr>\n</table>","G4639":"<h1>skia</h1>\n<p>Strong n° 4639 <i>Prononciation [skee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>ombre\n<ol type=\"a\">\n<li>ombre causée par l'interception de la lumière</li>\n<li>une image jetée par un objet et représentant la forme de cet objet</li>\n<li>un croquis, un aperçu, une esquisse</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σκιά, ᾶς (ἡ)</b> ombre :<br><b>   I</b> <i>au propre,</i> ombre d’une personne <i>ou</i> d’une chose, OD. <i>11, 207 ;</i> EUR. <i>Andr. 745, etc. ;</i> PLAT. <i>Phæd. 101</i> d, <i>etc. (sg. et pl</i>.) ; σκ. πετραίη, HÉS. <i>O. 587,</i> l’ombre d’un rocher ; ὑπὸ σκιῇ (<i>ion. p</i>. σκιᾷ) HDT. <i>7, 226,</i> à l’ombre ; <i>au plur</i>. XÉN. <i>Cyr. 8, 8, 17 ;</i> ὑπὸ σκιαῖς, XÉN. <i>Œc. 20, 18,</i> à l’ombre ; <i>particul. :</i><br><b>      1</b> <i>pour signifier une chose vaine :</i> μάχεσθαί τῳ περὶ σκιᾶς, XÉN. <i>Mem. 1, 6, 6,</i> disputer contre qqn pour une ombre ; <span>ὄνου σκιά</span>, PLAT. <i>Phædr. 260</i> c, l’ombre d’un âne, <i>càd. prov</i>. un rien, <i>comme la question de savoir si l’ombre d’un âne loué appartient au propriétaire ou au locataire ;</i> καπνοῦ σκιά, SOPH. <i>Ant. 1170,</i> l’ombre d’une fumée ; <i>abs</i>. σκιᾶς ὄναρ ἄνθρωπος, PD. <i>P. 8, 99,</i> l’homme est le songe d’une ombre ; <i>cf</i>. SOPH. <i>Aj. 126, 1236 ;</i> EUR. <i>Med. 1224 ;</i><br><b>      2</b> ombre dans un dessin, ESCHL. <i>Ag. 1288 ;</i> σκιᾶς ἀπόχρωσις <i>ou</i> φθορά, PLUT. <i>M. 407</i> a, <i>etc</i>. dégradation de l’ombre, clair-obscur ;<br><b>   II</b> ombre des morts, OD. <i>10, 495 ;</i> ESCHL. <i>Sept. 988 ;</i> SOPH. <i>Aj. 1257, etc. ;</i> EUR. <i>fr. 536, etc. ; p. anal</i>. ombre, fantôme, SOPH. <i>Aj. 301 ;</i><br><b>   III</b> ombre, convive non invité qu’on amenait avec soi à un repas, PLUT. <i>M. 707</i> d.<br><span><b><span class=\"arrow\"></span></b> <i>Le</i> σκ- <i>de</i> σκιά <i>ne fait pas position, par exception, dans</i> HÉS. <i>O. 587. Ion</i>. σκιή, HOM. HÉS. HDT. <i>ll. cc</i>.<br><span><b>Étym</b>. <i>indo-europ</i>. *skeh₂-ih₂-, ombre ; <i>cf. sscr</i>. chāyā́.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σκια - σκιά</font>\n<br><br>apparemment un mot primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n7 fois dans 7 versets de 6 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Luc (1)</li>\n<li>Actes (1)</li>\n<li>Colossiens (1)</li>\n<li>Hébreux (2)</li>\n</ul>\n</td></tr>\n</table>","G4640":"<h1>skirtao</h1>\n<p>Strong n° 4640 <i>Prononciation [skeer-tah'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>sauter, sursauter, tressaillir</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σκιρτάω-ῶ</b>, sauter, bondir, IL. <i>20, 226 ; joint à</i> ἅλλεσθαι, PLAT. <i>Leg. 653</i> c ; <i>à</i> ὀρχεῖσθαι <i>et</i> χορεύειν, AR. <i>Pl. 761 ; en parl. des Bacchantes,</i> EUR. <i>Bacch. 446 ; de jeunes chevaux,</i> EUR. <i>Ph. 1125 ; de chèvres,</i> THCR. <i>Idyl. 1, 152, etc. ; en parl. du vent (cf. franç</i>. une saute de vent) ESCHL. <i>Pr. 1086 ; fig</i>. PLAT. <i>Rsp. 571</i> c, <i>etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. σκιρτέω, OPP. <i>C. 4, 342</i>.<br><span><b>Étym</b>. <i>cf</i>. σκαίρω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σκιρταω - σκιρτάω</font>\n<br><br>parent de skairo (sauter)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 1 livre biblique (NT)\n<ul>\n<li>Luc (3)</li>\n</ul>\n</td></tr>\n</table>","G4641":"<h1>sklerokardia</h1>\n<p>Strong n° 4641 <i>Prononciation [sklay-rok-ar-dee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>la dureté de cœur</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σκληρο·καρδία, ας (ἡ)</b> dureté de cœur, SPT. <i>Deut. 10, 16 ; Sir. 16, 10 ; Jer. 4, 4 ;</i> NT. <i>Matth. 19, 8, Marc. 16, 14</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σκληροκαρδια - σκληροκαρδία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Marc (3)</li>\n</ul>\n</td></tr>\n</table>","G4642":"<h1>skleros</h1>\n<p>Strong n° 4642 <i>Prononciation [sklay-ros']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>dur, rude, abrupt, raide\n<ol type=\"a\">\n<li>des hommes : métaph. rude, sévère, dur</li>\n<li>de choses : violent, rude, offensif, intolérable</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σκληρός, ά, όν :<br>   I</b> <i>au propre,</i> sec, dur, <i>particul. :</i><br><b>      1</b> dur au toucher, <i>p. opp. à</i> μαλακός, THGN. <i>1194 ; en parl. de bois,</i> XÉN. <i>Œc. 16, 10 ; d’une couche,</i> PLAT. <i>Leg. 942</i> d, <i>etc. ;</i><br><b>      2</b> sec, <i>p. opp. à</i> humide (ὑγρός) AR. <i>Ach. 1199 ; en parl. de cire,</i> PLAT. <i>Theæt. 191</i> c ; κοιλία σκληρά, HPC. <i>Aph. 5, 3 ;</i> THPP. COM. <i>2, 813, etc</i>. selles dures ; τὸ σκληρόν, XÉN. <i>Eq. 10, 10, 11,</i> la partie sèche (<i>d’un mors), p. opp. à</i> τὸ ὑγρόν ; <i>en parl. de l’air, du vent,</i> POL. <i>4, 21, 5 ;</i> EL. <i>N.A. 9, 57, etc. ;</i><br><b>      3</b> <i>p. anal. en parl. d’un bruit :</i> σκλ. βρονταί, HDT. <i>8, 12,</i> coups de tonnerre secs ; σκληρὸν ἐϐρόντησε, HÉS. <i>Th. 839,</i> il tonna un coup sec ;<br><b>      4</b> <i>en parl. du goût, de la saveur,</i> sec, âpre, âcre, <i>en parl. d’eau,</i> ATH. <i>33</i> b ; <i>de vin,</i> AR. <i>fr. 563 ; de même en parl. d’odeurs,</i> TH. <i>C.P. 6, 14, 12 ; fig. en parl. du style,</i> DH. <i>Pomp. 1, 2, 6 ;</i><br><b>      5</b> <i>p. suite,</i> rigide, raide, <i>p. opp. à</i> souple, moelleux (μαλακός) <i>en parl. de cheveux,</i> ARSTT. <i>H.A. 3, 10, 4, etc. ; de peau,</i> ARSTT. <i>P.A. 3, 3, 14, etc. ; d’où en parl. de pers</i>. raide, guindé, PLAT. <i>Theæt. 162</i> b ; <i>en b. part,</i> ferme, solide, vigoureux, PLUT. <i>Ages. 13 ;</i> LUC. <i>Salt. 21, etc. ;</i><br><b>   II</b> <i>fig. :</i><br><b>      1</b> dur, rude, pénible : σκληρὰ ἀνάγκη, ANT. <i>121, 17,</i> dure nécessité ; σκληρὸς βίος, MÉN. <i>4, 224 Meineke</i> vie dure ; τροφὴ σκλ. SOPH. <i>O.C. 1615,</i> nourriture rude ; σκλ. δίαιτα, EUR. <i>fr. 529,</i> régime de vie dur ;<br><b>      2</b> <i>au mor</i>. rébarbatif, grincheux, <i>joint à</i> ἄγριοι, ARSTT. <i>Nic. 4, 8 ; à</i> ἀπειθής, T. LOCR. <i>104</i> c ;<br><b>      3</b> morose, sévère, SOPH. <i>fr. 19 ;</i> PLAT. <i>Theæt. 155</i> e ;<br><b>      4</b> <i>p. suite,</i> rigide, <i>p. opp. à</i> ἀπαίδευτος, PLUT. <i>Cim. 1 ;</i> rude, dur, inflexible, <i>en parl. du sphinx,</i> SOPH. <i>O.R. 36 ; de la divinité,</i> AR. <i>Nub. 1264 ;</i> EUR. <i>Alc. 500, etc</i>.<br><span>•<i> Cp</i>. σκληρότερος, PLAT. <i>Theæt. 191 c. ;</i> ARSTT. <i>H.A. 9, 5, etc. ;</i> <i>• Sup</i>. σκληρότατος, ATT.<br><span><b><span class=\"arrow\"></span></b> <i>Dor</i>. σκλαρός <span>[ᾱ]</span> T. LOCR. <i>l. c</i>.<br><span><b>Étym</b>. σκέλλω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σκληρος - σκληρός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 6 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Jean (1)</li>\n<li>Actes (2)</li>\n<li>Jacques (1)</li>\n<li>Jude (1)</li>\n</ul>\n</td></tr>\n</table>","G4643":"<h1>sklerotes</h1>\n<p>Strong n° 4643 <i>Prononciation [sklay-rot'-ace]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>dureté</li>\n<li>obstination, opiniâtreté</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σκληρότης, ητος (ἡ) :<br>   I</b> <i>au propre :</i><br><b>      1</b> dureté, rudesse, ARSTT. <i>P.A. 1, 4, 8, etc. ; p. opp. à</i> μαλακότης, PLAT. <i>Rsp. 523</i> e ;<br><b>      2</b> <i>en parl. de goût, de saveur,</i> âpreté, TH. <i>C.P. 6, 14, 12 ;</i><br><b>   II</b> <i>fig. :</i><br><b>      1</b> rudesse de caractère, PLAT. <i>Rsp. 410</i> d ; ARSTT. <i>Poet. 15, 11 ; joint à</i> ἀγροικία, PLAT. <i>Rsp. 607</i> b ;<br><b>      2</b> caractère rigoureux, rigueur, ANT. <i>122, 44</i>.<br><span><b>Étym</b>. σκληρός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σκληροτης - σκληρότης</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G4644":"<h1>sklerotrachelos</h1>\n<p>Strong n° 4644 <i>Prononciation [sklay-rot-rakh'-ay-los]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>au cou raide, nuque raide, rebelle, qui a du mal à comprendre</li>\n<li>opiniâtre, tête dure, obstiné</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σκληρο·τράχηλος, ος, ον</b> <span>[ᾰ]</span> qui a le cou dur, <i>fig</i>. entêté, SPT. <i>Ex. 33, 3, etc. ;</i> NT. <i>Ap. 7, 51</i>.<br><span><b>Étym</b>. σκληρός, τράχηλος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σκληροτραχηλος - σκληροτράχηλος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4645":"<h1>skleruno</h1>\n<p>Strong n° 4645 <i>Prononciation [sklay-roo'-no]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>rendre dur, durcir, endurcir</li>\n<li>métaph.\n<ol type=\"a\">\n<li>rendre obstiné, opiniâtre</li>\n<li>être endurci</li>\n<li>devenir obstiné ou têtu</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σκληρύνω</b> <span>(<i>f</i>. υνῶ, <i>ao. pass</i>. ἐσκληρύνθην)</span> <i>c</i>. σκληρόω, <i>p. opp. à</i> μαλάσσω, HPC. <i>Acut. 391 ;</i> ARSTT. <i>H.A. 5, 16, 7 ; au pass</i>. HPC. <i>V. med. 18, 427, 20 ; fig</i>. SPT. <i>Ex. 7, 3, etc. ;</i> NT. <i>Rom. 9, 18 ; Hebr. 3, 8 ; au pass</i>. SPT. <i>Sir. 30, 11</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Pf. pass</i>. ἐσκλήρυμμαι, HPC. <i>V. med. 18, ou</i> ἐσκλήρυσμαι, HPC. <i>427, 20</i>.<br><span><b>Étym</b>. σκληρός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σκληρυνω - σκληρύνω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 6 versets de 3 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>Romains (1)</li>\n<li>Hébreux (4)</li>\n</ul>\n</td></tr>\n</table>","G4646":"<h1>skolios</h1>\n<p>Strong n° 4646 <i>Prononciation [skol-ee-os']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>tortueux, tordu, recourbé</li>\n<li>métaph.\n<ol type=\"a\">\n<li>pervers, méchant</li>\n<li>injuste, maussade, bourru</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σκολιός, ά, όν :<br>   I</b> <i>au propre :</i><br><b>      1</b> oblique, tortueux, HDT. <i>1, 185, etc. ;</i> EUR. <i>Hec. 65 ;</i> ARSTT. <i>Meteor. 2, 8, 25 ;</i> A. RH. <i>4, 1541 ;</i> NIC. <i>Th. 478 ;</i> STR. <i>577, etc. ;</i><br><b>      2</b> tourné de côté (tête, pieds, <i>etc</i>.) THGN. <i>536 ;</i> PD. <i>fr. 217, etc. ;</i><br><b>   II</b> <i>fig</i>. tortueux : μῦθοι σκολιοί, HÉS. <i>O. 192, etc</i>. paroles tortueuses, sans franchise ; πράττειν σκολιά, PLAT. <i>Theæt. 173</i> a, agir d’une manière tortueuse ; <i>en parl. de pers</i>. HÉS. <i>O. 7 ; joint à</i> φοϐερός, PLUT. <i>M. 551</i> f.<br><span><b>Étym</b>. σκέλος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σκολιος - σκολιός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 4 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Actes (1)</li>\n<li>Philippiens (1)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G4647":"<h1>skolops</h1>\n<p>Strong n° 4647 <i>Prononciation [skol'-ops]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un morceau de bois pointu, un pal, un pieu</li>\n<li>un pieu pointu, un éclat, une écharde</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σκόλοψ, οπος (ὁ) :<br>   I</b> bois pointu, <i>particul. :</i><br><b>      1</b> pieu, <i>d’où</i> palissade, IL. <i>7, 441 ; 8, 343, etc. ;</i> OD. <i>7, 45, etc. ;</i> HDT. <i>9, 97 ;</i> XÉN. <i>An. 5, 2, 5 ;</i><br><b>      2</b> pieu sur lequel on fiche une tête, IL. <i>18, 177 ;</i><br><b>      3</b> pal, EUR. <i>El. 898 ; I.T. 1430, etc. ;</i> PLUT. <i>M. 499</i> c ;<br><b>      4</b> <i>postér</i>. croix, DS. <i>Exc. 596, 65 ;</i><br><b>      5</b> épine, aiguillon, éclat de bois, écharde, SPT. <i>Num. 33, 55, etc. ;</i> DIOSC. <i>4, 49, etc. ;</i><br><b>      6</b> instrument de chirurgien, ORIB. <i>p. 187 Mai ;</i><br><b>      7</b> pointe d’hameçon, LUC. <i>M. cond. 3 ;</i><br><b>   II</b> bois qui se dresse, <i>en gén., d’où</i> arbre, EUR. <i>Bacch. 983</i>.<br><span><b>Étym</b>. <i>pré-grec</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σκολοψ - σκόλοψ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4648":"<h1>skopeo</h1>\n<p>Strong n° 4648 <i>Prononciation [skop-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>regarder, observer, contempler</li>\n<li>remarquer</li>\n<li>fixer les yeux sur, diriger son attention sur</li>\n<li>« prends garde toi-même »</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σκοπέω-ῶ</b> (<i>seul. prés. et impf. ; pour le fut., l’ao. et le pf. on emploie les temps correspond. de</i> σκέπτομαι ; <i>sur l’ao. réc</i>. ἐσκόπησα, <i>v. ci-dessous</i>) :<br><b>      1</b> observer de haut <i>ou</i> de loin : ἄστρον, PD. <i>O. 1, 8,</i> un astre ; τὰ πόρρω, EUR. <i>Rhes. 482 ;</i> τὰ ἔμπροσθεν, XÉN. <i>An. 6, 1 (3), 14,</i> ce qui est au loin, ce qui est devant ; <i>avec une prop. dépendante :</i> σκ. ὅπου, <i>etc</i>. SOPH. <i>Ph. 16 ;</i> σκ. ποῦ, etc. XÉN. <i>Cyr. 3, 2, 1,</i> regarder où, <i>etc. ; avec une prép. :</i> σκ. εἴς τι, PLAT. <i>Pol. 305</i> b, observer qqe ch. ; <i>abs</i>. ESCHL. <i>Suppl. 232 ;</i> SOPH. <i>O.R. 69 ; joint à</i> φυλάττειν, XÉN. <i>An. 5, 1, 9 ;</i><br><b>      2</b> viser à, avoir en vue, avoir pour but, <i>acc</i>. XÉN. <i>An. 5, 7, 32, etc. ;</i> οἱ εὐτέλειαν μᾶλλον ἢ πολυχρηματίαν σκοποῦντες, XÉN. <i>Conv. 4, 42,</i> ceux qui recherchent la simplicité plutôt que l’abondance ; <i>p. suite,</i> avoir égard à, veiller à, prendre soin de : τὰ ἑωυτοῦ, HDT. <i>1, 8,</i> à ses propres intérêts ; <i>cf</i>. PLAT. <i>Phædr. 232</i> d ; LUC. <i>Prom. 14 ;</i><br><b>      3</b> regarder, examiner, considérer, observer, <i>acc</i>. SOPH. <i>Ph. 282, O.R. 130, etc. ;</i> ἄνθρωπον σκοπῶν ἢ πρὸς ὑγίειαν ἢ πρὸς ἄλλο τι, PLAT. <i>Prot. 352</i> a, observant l’homme soit pour son état de santé, soit pour qqe autre chose ;<br><b>      4</b> réfléchir à, peser, examiner, juger : <i>rar. au pass</i>. être observé, examiné, PLAT. <i>Leg. 772</i> d ; <i>avec l’acc. :</i> σκ. τὰ ἔργα ἑκάστου, XÉN. <i>Cyr. 2, 2, 18,</i> examiner les actions de chacun ; <i>cf</i>. XÉN. <i>Mem. 1, 1, 12, etc. ; avec l’acc. et une propos. dépendante :</i> σκοπέειν χρὴ παντὸς χρήματος τὴν τελευτήν, κῇ ἀποϐήσεται, HDT. <i>1, 32,</i> en toute chose il faut considérer la fin, voir ce qu’il en adviendra ; <i>cf</i>. SOPH. <i>Ph. 506 ;</i> XÉN. <i>Mem. 2, 5, 5 ;</i> σκ. οὐδὲν ἄλλο ἢ εἰ, XÉN. <i>An. 7, 4, 8,</i> ne rien considérer autre chose sinon si, <i>etc. ; de même avec</i> ὅπως, SOPH. <i>O.R. 407 ;</i> XÉN. <i>Hipp. 7, 15, etc. ;</i> ὅτι, XÉN. <i>Mem. 3, 9, 8 ;</i> οἷος, SOPH. <i>O.C. 369, etc. ; avec une propos. dépendante annoncée par</i> εἰ, SOPH. <i>Ant. 41 ; par</i> μή, SOPH. <i>O.C. 1179 ;</i> DÉM. <i>563, 27 ; par</i> ὅπως, PLAT. <i>Gorg. 526</i> d ; DÉM. <i>118, 19 ; par</i> ὅτι, XÉN. <i>Mem. 2, 10, 6, etc. ; avec le gén. et un acc. ou une propos. dépend. :</i> σκόπει δὴ καὶ τόδε αὐτῶν, PLAT. <i>Theæt. 182</i> a, observe donc aussi ceci chez eux ; τινὸς σκ. πότερα, <i>etc</i>. XÉN. <i>Mem. 1, 1, 12,</i> observer au sujet de qqn laquelle de deux choses, <i>etc. ; avec une prép. :</i> σκ. ἔκ τινος, THC. <i>6, 36,</i> examiner d’après qqe ch.(d’après ce que l’on rapporte) ; σκ. περί τινος, XÉN. <i>Mem. 4, 6, 2 ;</i> considérer au sujet de qqe ch., <i>etc. ;</i> σκ. πρός τι, XÉN. <i>Cyr. 1, 6, 8 ; An. 1, 9, 22, etc</i>. avoir en vue qqe ch. ; πρός τινα σκ. PLAT. <i>Rsp. 348</i> b, avoir qqn en vue, penser à qqn (<i>ttef</i>. σκοπῶ πρὸς ἐμαυτόν, PLAT. <i>Euthyphr. 9</i> c, je considère en moi-même) ; <i>avec un adv. :</i> σὺ δὲ δὴ ποῖ σκοπεῖς ; PLAT. <i>Leg. 963</i> b, mais toi, qu’as-tu donc en vue ? οὐκ ὀρθῶς σκ. THC. <i>3, 12,</i> ne pas considérer avec rectitude ; <i>cf</i>. XÉN. <i>Vect. 5, 2, etc. ;</i><br><b><i>Moy.</i></b> :<br><b>      1</b> regarder, considérer, <i>abs</i>. EUR. <i>I.T. 68 ;</i> σκ. ἀπὸ τῶν ἱστῶν, XÉN. <i>Hell. 6, 2, 29,</i> observer du haut des mâts ; <i>avec un acc. :</i> σκ. τὸν ἥλιον ἐκλείποντα, PLAT. <i>Phæd. 99</i> d, observer l’éclipse de soleil ;<br><b>      2</b> avoir en vue, chercher : ἀπολογίαν, ISOCR. <i>403</i> a, une excuse ;<br><b>      3</b> examiner, réfléchir, <i>avec l’acc. et une prop. dépend. :</i> τὰς τύχας τῶν βροτῶν ὡς, etc. EUR. <i>fr. 266 Nauck,</i> observer les destinées des mortels comme, <i>etc. ; avec un relat. :</i> πότερον, XÉN. <i>An. 5, 2, 8 ;</i> ὅπου, XÉN. <i>Cyn. 9, 18 ;</i> ὅπως, XÉN. <i>Hipp. 1, 6, etc. ;</i> τί, POL. <i>12, 14, 3 ; avec une prép. ou un adv. :</i> σκ. περί τινος, XÉN. <i>Hier. 1, 10 ;</i> PLAT. <i>1 Alc. 107</i> c, réfléchir au sujet de qqe ch. ; σκ. πρός τι, PLAT. <i>Leg. 645</i> d, réfléchir en vue de qqe ch. ; σκ. ἀκριϐῶς, ARSTT. <i>H.A. 4, 8 ;</i> ὀρθῶς σκ. POL. <i>1, 8, 5,</i> observer avec soin, avec justesse.<br><span><b><span class=\"arrow\"></span></b> <i>Act. prés. inf. ion</i>. σκοπέειν, HDT. <i>1, 32 ; ao. réc</i>. ἐσκόπησα, ARSTT. <i>Plant. 1, 7, 10 ;</i> TH. <i>Sign. 1, 1, etc</i>.<br><span><b>Étym</b>. σκοπός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σκοπεω - σκοπέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n7 fois dans 6 versets de 5 livres bibliques (NT)\n<ul>\n<li>Luc (2)</li>\n<li>Romains (1)</li>\n<li>2 Corinthiens (1)</li>\n<li>Galates (1)</li>\n<li>Philippiens (2)</li>\n</ul>\n</td></tr>\n</table>","G4649":"<h1>skopos</h1>\n<p>Strong n° 4649 <i>Prononciation [skop-os']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un observateur, un veilleur</li>\n<li>la marque distante que l'on regarde, le but que quelqu'un a en vue terme d'une course</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σκοπός, οῦ :<br>   I</b> <i>act</i>. (ὁ, ἡ) celui <i>ou</i> celle qui observe, <i>particul. :</i><br><b>      1</b> celui qui observe de haut <i>ou</i> de loin, IL. <i>2, 792 ;</i> XÉN. <i>Cyr. 3, 2, 1, etc. ;</i> σκοποὶ ἷζον ἐπ' ἄκριας ἠνεμοέσσας, OD. <i>16, 365,</i> des observateurs étaient postés sur les hauteurs battues des vents ; <i>p. anal. en parl. du soleil,</i> HH. <i>Cer. 62 ; p. suite,</i> espion, IL. <i>10, 324, 526, 561 ; ou en gén</i>. messager envoyé pour prendre des informations, ESCHL. <i>Sept. 36, etc. ;</i> SOPH. <i>O.C. 35, etc. ;</i> EUR. <i>Rhes. 556 ;</i><br><b>      2</b> <i>en gén</i>. surveillant, surveillante ; gardien, gardienne, <i>d’où</i> maître, IL. <i>23, 359 ;</i> OD. <i>22, 156 ;</i> SOPH. <i>Aj. 945 ;</i> σκ. γυναικῶν δμῳάων, OD. <i>22, 396,</i> surveillante des femmes de service ; <i>particul</i>. surveillant des jeux, XÉN. <i>Cyr. 1, 6, 40 ;</i><br><b>      3</b> celui qui veille sur, protecteur, protectrice, <i>d’ord. en parl. des dieux <i>ou</i> des rois :</i> Ὀλύμπου σκοποί, PD. <i>O. 1, 86,</i> les dieux protecteurs de l’Olympe ; <i>cf</i>. PD. <i>N. 5, 51 ;</i><br><b>   II</b> <i>pass</i>. ὁ σκοπός, but : πρὸς σκοπὸν βλέπειν, PLAT. <i>Gorg. 507</i> d, avoir les yeux fixés sur un but ; σκοπὸν βάλλειν, OD. <i>22, 6 ;</i> ἐπὶ σκοπὸν βάλλειν, XÉN. <i>Cyr. 1, 6, 29,</i> viser (chercher à atteindre) le but ; σκοποῦ τυχεῖν, PD. <i>N. 6, 46 ;</i> ANT. <i>121, 31,</i> toucher le but ; σκοποῦ ἀποτυγχάνειν, PLAT. <i>Leg. 744</i> a, <i>ou</i> ἁμαρτεῖν, PLAT. <i>Theæt. 194</i> a, manquer le but ; πρὸς σκοπόν τινα ποιεῖν τι, POL. <i>15, 26, 6,</i> faire qqe ch. en vue d’un certain but ; ἀπὸ σκοποῦ, OD. <i>11, 344 ;</i> PLAT. <i>Theæt. 179</i> c ; <i>ou</i> ἀπὸ τοῦ σκοποῦ, XÉN. <i>Conv. 2, 10 ;</i> παρὰ σκοπόν, PD. <i>O. 13, 134,</i> en dehors <i>ou</i> loin du but, <i>p. suite,</i> hors de propos ;<br><b>   III</b> sorte de danse, EUP. <i>2-1, 575 Meineke</i>.<br><span><b><span class=\"arrow\"></span></b> ἡ σκ. OD. <i>22, 396 ;</i> CALL. <i>Del. 66</i>.<br><span><b>Étym</b>. σκέπτομαι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σκοπος - σκοπός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Philippiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4650":"<h1>skorpizo</h1>\n<p>Strong n° 4650 <i>Prononciation [skor-pid'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>éparpiller\n<ol type=\"a\">\n<li>de ceux qui, mis en déroute ou terrorisés ou conduits par leurs impulsions, fuient dans toutes les directions</li>\n<li>disperser (ce que les autres ont pu accumuler), ou quelqu'un qui gaspille littéralement ses bénédictions</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σκορπίζω</b> <span>(<i>ao. pass. inf</i>. σκορπισθῆναι)</span> disperser <i>comme avec l’engin</i> σκορπίος, HÉCAT. <i>fr. 371 ;</i> STR. <i>198 ;</i> LUC. <i>As. 32 ;</i> NT. <i>Matth. 12, 30 ; Luc. 11, 23 ; au pass</i>. PLUT. <i>Tim. 4 ;</i> NT. <i>Joh. 16, 32</i>.<br><span><b>Étym</b>. σκορπίος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σκορπιζω - σκορπίζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (1)</li>\n<li>Jean (2)</li>\n<li>2 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4651":"<h1>skorpios</h1>\n<p>Strong n° 4651 <i>Prononciation [skor-pee'-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un scorpion, le nom d'un petit animal, ressemblant un peu à un homard, qui se cache dans les régions chaudes, sous les pierres ; il a un aiguillon avec un venin mortel dans la queue</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σκορπίος, ου (ὁ) :<br>   I</b> <i>nom d’animaux :</i><br><b>      1</b> scorpion, <i>arachnide venimeux,</i> ESCHL. <i>fr. 155 ;</i> SOPH. <i>fr. 35 Dind. ;</i> PLAT. <i>Euthyd. 290</i> a ; <i>fig. en parl. d’un homme méchant,</i> DÉM. <i>786, 4 ;</i> ANTH. <i>11, 227 ;</i><br><b>      2</b> scorpion de mer (<i>collus scorpio</i> L.) <i>poisson,</i> ARSTT. <i>H.A. 2, 17 ; 5, 9 ; 8, 13 ;</i> COM. (ATH. <i>320</i> d) ;<br><b>   II</b> <i>p. anal. :</i><br><b>      1</b> sorte d’ajonc (<i>spartium scorpio</i> L.) <i>plante épineuse,</i> TH. <i>H.P. 9, 18, 2 ;</i><br><b>      2</b> scorpion, <i>machine de jet de gros calibre,</i> PLUT. <i>Marc. 15 ;</i> HÉRON <i>Bel. p. 122</i> c ;<br><b>      3</b> sorte de pierre, ORPH. <i>Lith. 488 ;</i><br><b>      4</b> le Scorpion, <i>constellation,</i> Ps.-ERATOSTH. <i>Cat. 7</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σκορπιος - σκορπίος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 2 livres bibliques (NT)\n<ul>\n<li>Luc (2)</li>\n<li>Apocalypse (3)</li>\n</ul>\n</td></tr>\n</table>","G4652":"<h1>skoteinos</h1>\n<p>Strong n° 4652 <i>Prononciation [skot-i-nos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>dans l'obscurité, couvert de ténèbres, sombre, obscur, ténébreux</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σκοτεινός, ή, όν :<br>   I</b> ténébreux, sombre, obscur, ESCHL. <i>Ch. 661, etc. ;</i> XÉN. <i>Cyn. 6, 5 ;</i> PLAT. <i>Rsp. 432</i> c, <i>etc. ;</i> τὸ σκοτεινόν, THC. <i>3, 22 ;</i> τὰ σκοτεινά, les ténèbres, XÉN. <i>Mem. 3, 10, 1 ;</i> PLAT. <i>Rsp. 520</i> c ; <i>ou</i> les ombres en peinture, PLUT. <i>M. 57</i> c ; <i>fig. :</i><br><b>      1</b> obscur, <i>etc. ; p. opp. à</i> φανός, PLAT. <i>Conv. 197</i> a ; <i>joint à</i> δυσδιερεύνητος, PLAT. <i>Rsp. 432</i> c ; <i>en parl. d’Héraclite,</i> ARSTT. <i>Mund. 5, 5 ;</i><br><b>      2</b> secret, EUR. <i>fr. 290 ;</i><br><b>   II</b> qui est dans les ténèbres, <i>d’où :</i><br><b>      1</b> aveugle, SOPH. <i>O.R. 1326 ;</i> EUR. <i>Alc. 385 ;</i><br><b>      2</b> <i>p. anal</i>. sourd, PLAT. <i>Criti. 109</i> e.<br><span><b>Étym</b>. σκότος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σκοτεινος - σκοτεινός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (2)</li>\n</ul>\n</td></tr>\n</table>","G4653":"<h1>skotia</h1>\n<p>Strong n° 4653 <i>Prononciation [skot-ee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>ténèbres</li>\n<li>l'obscurité provenant d'un manque de lumière</li>\n<li>métaph. utilisé pour l'ignorance des choses divines, la méchanceté qui lui est associée, la misère qui en résulte en enfer</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σκοτία, ας (ἡ) :<br>   I</b> ténèbres, obscurité, A. RH. <i>4, 1698 ;</i> ANTH. <i>8, 187, 190 ;</i><br><b>   II</b> <i>t. d’archit. :</i><br><b>      1</b> triglyphe, <i>c</i>. τροχίλος, VITR. <i>3, 5, 2 ;</i><br><b>      2</b> sorte de gouttière, VITR. <i>4, 3, 6</i>.<br><span><b>Étym</b>. σκότος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σκοτια - σκοτία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n16 fois dans 12 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (1)</li>\n<li>Jean (8)</li>\n<li>1 Jean (6)</li>\n</ul>\n</td></tr>\n</table>","G4654":"<h1>skotizo</h1>\n<p>Strong n° 4654 <i>Prononciation [skot-id-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>couvert par les ténèbres, obscurcir</li>\n<li>être dans l'obscurité, être obscurci\n<ol type=\"a\">\n<li>des corps célestes qui sont privés de lumière</li>\n<li>métaph.\n<ol>\n<li>des yeux</li>\n<li>de la compréhension</li>\n<li>de l'esprit</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σκοτίζω</b>, couvrir de ténèbres, THÉM. <i>153</i> a ; <i>au pass</i>. PLUT. <i>M. 1120</i> e ; SPT. <i>Ps. 68, 24 ; Eccl. 12, 2 ; 3 Macc. 4, 10 ;</i> NT. <i>Eph. 4, 18</i>.<br><span><b>Étym</b>. σκότος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σκοτιζω - σκοτίζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n8 fois dans 8 versets de 6 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Luc (1)</li>\n<li>Romains (2)</li>\n<li>Ephésiens (1)</li>\n<li>Apocalypse (2)</li>\n</ul>\n</td></tr>\n</table>","G4655":"<h1>skotos</h1>\n<p>Strong n° 4655 <i>Prononciation [skot'-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>ténèbres\n<ol type=\"a\">\n<li>de l'obscurité de la nuit</li>\n<li>de la vue obscurcie ou cécité</li>\n</ol>\n</li>\n<li>métaph.\n<ol type=\"a\">\n<li>de l'ignorance concernant les choses divines, devoirs humains, ce qui accompagne l'impiété et l'immoralité, avec toute la misère que ceci implique en enfer</li>\n<li>les personnes dans lesquelles l'obscurité devient visible et les dirige</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n➀ <b>σκότος, ου (ὁ) :<br>   I</b> ténèbres, obscurité, OD. <i>19, 389 ;</i> ATH. ; <i>p. opp. à</i> φάος, ESCHL. <i>Ch. 320, etc. ; à</i> ἡμέρα, PLAT. <i>Def. 411</i> b, <i>etc. ;</i> ἐν σκότῳ, SOPH. <i>Ant. 494, etc. ;</i> ὑπὸ σκότῳ, ESCHL. <i>Ag. 1030, etc. ;</i> ὑπὸ σκότου, XÉN. <i>Cyr. 4, 6, 4 ; fig</i>. κατὰ σκότον, SOPH. <i>Ph. 578,</i> dans l’obscurité, dans l’ombre ; ὑπὸ σκότου, SOPH. <i>Ant. 692,</i> furtivement ; ὁ Σκότος, les Ténèbres <i>personnifiées,</i> SOPH. <i>O.C. 40 ; particul. :</i><br><b>      1</b> ténèbres de la mort, IL. <i>4, 461 ; 6, 11, etc. ;</i> EUR. <i>Hipp. 837, etc. ;</i><br><b>      2</b> ténèbres des enfers, ESCHL. <i>Eum. 72, etc. ;</i> SOPH. <i>O.C. 1701, etc. ;</i> EUR. <i>Hel. 62, etc. ; d’où</i> les enfers, EUR. <i>Hec. 1 ;</i><br><b>      3</b> cécité, SOPH. <i>O.R. 1313 ;</i> σκότον δεδορκώς ; EUR. <i>Ph. 377,</i> qui ne voit que les ténèbres, aveugle ;<br><b>      4</b> vertige, éblouissement, HPC. <i>1149</i> b ; ARSTT. <i>H.A. 7, 4, 3 ;</i><br><b>   II</b> <i>fig. :</i><br><b>      1</b> vie obscure, PD. <i>N. 7, 19 ;</i> PLAT. <i>Leg. 837</i> a, <i>etc. ;</i><br><b>      2</b> infortune, THCR. <i>Idyl. 29, 8 ;</i><br><b>      3</b> obscurité, incertitude, aveuglement de l’esprit, <i>d’où</i> ignorance, DÉM. <i>411, 25 ; p. suite,</i> erreur, déception, PLAT. <i>Leg. 864</i> c ;<br><b>      4</b> ruse, <i>joint à</i> ἀπάτη, PLAT. <i>Leg. 864</i> c ; <i>d’où</i> coquin, filou, <i>litt</i>. qui agit dans l’ombre, HIPPON. <i>fr. 123</i>.<br><span><b>Étym</b>. <i>indo-europ</i>. *sk(e)h₃t- <i>ou</i> *skoto-, ombre, obscur ; <i>la relation avec</i> σκιά <i>n’est pas claire</i>.</span><br><br>\n➁ <b>σκότος, εος-ους (τὸ)</b> <i>c</i>. σκότος SOPH. <i>O.C. 40 ;</i> EUR. <i>Hec. 831, etc. ;</i> HDT. <i>2, 121 ;</i> XÉN. <i>An. 2, 5, 9, etc. ;</i> DÉM. <i>281, 3, etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σκοτος - σκότος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n32 fois dans 31 versets de 16 livres bibliques (NT)\n<ul>\n<li>Matthieu (7)</li>\n<li>Marc (1)</li>\n<li>Luc (4)</li>\n<li>Jean (1)</li>\n<li>Actes (3)</li>\n<li>Romains (2)</li>\n<li>1 Corinthiens (1)</li>\n<li>2 Corinthiens (2)</li>\n<li>Ephésiens (3)</li>\n<li>Colossiens (1)</li>\n<li>1 Thessaloniciens (2)</li>\n<li>Hébreux (1)</li>\n<li>1 Pierre (1)</li>\n<li>2 Pierre (1)</li>\n<li>1 Jean (1)</li>\n<li>Jude (1)</li>\n</ul>\n</td></tr>\n</table>","G4656":"<h1>skotoo</h1>\n<p>Strong n° 4656 <i>Prononciation [skot-o'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>obscurcir, couvrir de ténèbres</li>\n<li>métaph. obscurcir ou aveugler l'esprit</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σκοτόω-ῶ :<br>      1</b> couvrir de ténèbres, <i>acc</i>. SOPH. <i>Aj. 85 ;</i><br><b>      2</b> aveugler par un éblouissement, <i>d’où au pass</i>. avoir le vertige, HPC. <i>1154, 5 ;</i> PLAT. <i>Rsp. 518</i> a, <i>Prot. 339</i> e, <i>Theæt. 209</i> e ; POL. <i>10, 13, 8 ;</i> PLUT. <i>M. 489</i> f.<br><span><b>Étym</b>. σκότος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σκοτοω - σκοτόω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G4657":"<h1>skubalon</h1>\n<p>Strong n° 4657 <i>Prononciation [skoo'-bal-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>tout déchet, comme l'excrément des animaux, les rebuts, la lie\n<ol type=\"a\">\n<li>de choses indignes, sans valeur et détestables</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σκύϐαλον, ου (τὸ)</b> <span>[ῠᾰ]</span><br><b>      1</b> débris jeté de côté, restes d’un repas, PLUT. <i>M. 693</i> e ; ANTH. <i>6, 302, 303 ;</i> écume <i>ou</i> débris déposés par la mer, ANTH. <i>7, 276 ;</i> cendres, ANTH. <i>7, 382 ;</i><br><b>      2</b> <i>p. ext</i>. ce qu’on rejette <i>en gén.,</i> excrément, PLUT. <i>M. 352</i> d ; A. APHR. <i>Probl. 1, 18 ;</i> ARÉT. <i>Caus. m. diut. 1, 15, etc</i>.<br><span><b>Étym</b>. <i>pré-grec</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σκυβαλον - σκύβαλον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Philippiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4658":"<h1>Skuthes</h1>\n<p>Strong n° 4658 <i>Prononciation [skoo'-thace]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Scythe (Angl. Scythian) = « grossier ou rude »\n<ol>\n<li>un Scythe, un habitant de la Scythie, l'actuelle Russie\n<ol type=\"a\">\n<li>pour la plupart des nations civilisées de l'antiquité, les Scythes étaient considérés comme les plus sauvages des barbares</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Σκύθης, ου (ὁ)</b> <span>[ῠ]</span><br><b>   I</b> Scythe, <i>au pl</i>. οἱ Σκύθαι, les Scythes, <i>n. commun à tous les peuples du N. E. de l’Europe et du N. de l’Asie,</i> HÉS. <i>fr. 17 Gaisford ;</i> HDT. <i>7, 163, etc. ; prov</i>. <span>Σκυθῶν ἐρημία</span>, AR. <i>Ach. 704,</i> un désert de Scythes ; <i>cf</i>. ESCHL. <i>Pr. 2 ; p. ext</i>. homme inculte, grossier, brutal, PLUT. <i>M. 847</i> f ; <i>à Athènes,</i> garde de police (<i>ce corps étant surtout composé de Scythes</i>) AR. <i>Th. 1017, 1026, Lys. 451 ;</i><br><b>   II</b> de Scythe, des Scythes, ESCHL. <i>Pr. 417, Sept. 817 ;</i> TH. <i>Lap. 55 ;</i><br><b>   III</b> Skythès <i>ou</i> le Scythe :<br><b>      1</b> <i>fils d’Hèraklès,</i> HDT. <i>4, 10 ;</i><br><b>      2</b> <i>autres,</i> HDT. <i>6, 23, etc. ;</i> XÉN. <i>Hell. 3, 4, 20, etc</i>.<br><i>Voc</i>. Σκύθα <span>[ῠ]</span> AR. <i>Th. 1112, etc. Gén. ion</i>. Σκύθεω, HDT. <i>7, 163</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Σκυθης - Σκύθης</font>\n<br><br>probablement d'origine étrangère</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Colossiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4659":"<h1>skuthropos</h1>\n<p>Strong n° 4659 <i>Prononciation [skoo-thro-pos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>d'un aspect sombre et triste</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σκυθρ·ωπός, ός, όν</b> <span>[ῠ]</span><br><b>      1</b> sombre, triste, chagrin, ESCHL. <i>Ch. 738 ;</i> EUR. <i>Med. 271, etc. ;</i> XÉN. <i>Mem. 3, 10, 4, etc. ;</i> σκ. ἡμέρα, PLUT. <i>Dem. 30,</i> jour néfaste ; τὸ σκυθρωπόν, EUR. <i>Alc. 797 ;</i> PLAT. <i>Conv. 206</i> d, air sombre, tristesse ; <i>p. ext</i>. grave, sévère, <i>en parl. d’une gravité affectée,</i> DÉM. <i>1122, 20 ;</i> ESCHN. <i>56, 31 ;</i><br><b>      2</b> de couleur sombre, PHILSTR. <i>Im. p. 378</i>.<br><span>•<i> Cp</i>. -ότερος, ARCHYT. (STOB. <i>Fl. 1, 70) ; sup</i>. -ότατος, PAUS.<br><span><b><span class=\"arrow\"></span></b> <i>Fém</i>. -ή, HPC. <i>1114</i> a ; EPHOR. <i>fr. 155 Müller ;</i> PLUT. <i>M. 417</i> c.<br><span><b>Étym</b>. σκυθρός, ὤψ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σκυθρωπος - σκυθρωπός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G4660":"<h1>skullo</h1>\n<p>Strong n° 4660 <i>Prononciation [skool'-lo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>écorcher</li>\n<li>déchirer, mutiler\n<ol type=\"a\">\n<li>vexer, affliger, ennuyer, importuner</li>\n<li>se donner de la peine, s'inquiéter</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σκύλλω</b> <span>(<i>f. inus. ; ao</i>. ἔσκυλα <span>[ῡ]</span>, <i>pass. ao</i>. ἐσκύλθην, <i>ao.2</i> ἐσκύλην, <i>pf</i>. ἔσκυλμαι)</span><br><b>   I</b> écorcher, déchirer, ESCHL. <i>Pers. 577 ;</i><br><b>   II</b> <i>p. ext. :</i><br><b>      1</b> arracher les cheveux, ANTH. <i>3, 175 ; 5, 259 ;</i><br><b>      2</b> tourmenter, HDN <i>7, 3 ; d’où</i> fatiguer, HDN <i>4, 13 ;</i><br><b><i>Moy.</i></b> :<br><b>      1 <i>intr.</i></b> se tourmenter, NT. <i>Luc. 7, 6 ; Matth. 9, 36 ;</i><br><b>      2 <i>tr.</i></b> arracher (les cheveux) NIC. <i>Al. 412</i>.<br><span><b>Étym</b>. <i>p.-ê. rapprochement avec</i> σκάλλω ; <i>cf</i>. σκύλος, σκύλμα.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σκυλλω - σκύλλω</font>\n<br><br>apparemment un verbe primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>Luc (3)</li>\n</ul>\n</td></tr>\n</table>","G4661":"<h1>skulon</h1>\n<p>Strong n° 4661 <i>Prononciation [skoo'-lon]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une peau de bête qui a été dépouillée, une fourrure</li>\n<li>les armes et les biens de valeur saisis d'un ennemi, les dépouilles</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n➀ <b>σκύλον, ου (τὸ)</b> <span>[ῡ]</span> dépouille d’un animal écorché, peau de bête, CALL. <i>fr. 142 dout</i>.<br><span><b>Étym</b>. <i>cf</i>. σκύλος.</span><br><br>\n➁ <b>σκῦλον, ου (τὸ)</b> <span>[ῡ]</span> dépouille d’un ennemi tué, EUR. <i>El. 897, Rhes. 620 ;</i> D. CHR. <i>Or. 64 ; d’ord. au pl</i>. SOPH. <i>Ph. 1428, 1431 ;</i> EUR. <i>I.T. 74, etc. ;</i> THC. <i>4, 134 ; fig. au sg</i>. PLUT. <i>Mar. 9</i>.<br><span><b>Étym</b>. <i>probabl. de la</i> R. <i>de</i> σκύλλω <i>ou p.-ê. pré-grec</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σκυλον - σκῦλον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G4662":"<h1>skolekobrotos</h1>\n<p>Strong n° 4662 <i>Prononciation [sko-lay-kob'-ro-tos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>mangé de vers</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σκωληκό·ϐρωτος, ος, ον :<br>      1</b> mangé des vers, NT. <i>Ap. 12, 23 ;</i><br><b>      2</b> piqué des vers, TH. <i>C.P. 5, 9, 1</i>.<br><span><b>Étym</b>. σκώληξ, βιϐρώσκω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σκωληκοβρωτος - σκωληκόβρωτος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4663":"<h1>skolex</h1>\n<p>Strong n° 4663 <i>Prononciation [sko'-lakes]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un ver, spéc. ceux qui rongent les cadavres (d'après <a class=\"ref\" data-r=\"ISA66.24\">Esaïe 66.24</a> le ver qui dévore le damné est un tourment éternel)</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σκώληξ, ηκος (ὁ) :<br>   I</b> ver, <i>particul. :</i><br><b>      1</b> ver de terre, IL. <i>13, 654 ;</i><br><b>      2</b> larve d’insecte, AR. <i>Vesp. 1111 ; fr. 503 ;</i> ARSTT. <i>H.A. 1, 5, 3 ;</i><br><b>      3</b> ver dans les arbres et dans le bois, ARSTT. <i>H.A. 5, 19, 3, etc. ;</i> TH. <i>H.P. 3, 12, 6, etc. ;</i><br><b>      4</b> ver dans les animaux, ARSTT. <i>H.A. 2, 15, 10, etc. ;</i><br><b>   II</b> <i>p. anal. :</i><br><b>      1</b> fil qu’on déroule, EPIGEN. <i>3, 540 Meineke ;</i><br><b>      2</b> vague qui s’allonge, PLAT. COM. <i>2-2, 623 Mein. ; cf</i>. κολόκυμα ;<br><b>      3</b> sorte de gâteau, ALCIPHR. <i>fr. 6, 10</i>.<br><span><b>Étym</b>. <i>incert</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σκωληξ - σκώληξ</font>\n<br><br>dérivation incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Marc (1)</li>\n</ul>\n</td></tr>\n</table>","G4664":"<h1>smaragdinos</h1>\n<p>Strong n° 4664 <i>Prononciation [smar-ag'-dee-nos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>émeraude, fait avec de l'émeraude</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σμαράγδινος, η, ον</b> <span>[μᾰῐ]</span> d’un vert d’émeraude, NT. <i>Apoc. 4, 3</i>.<br><span><b>Étym</b>. σμάραγδος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σμαραγδινος - σμαράγδινος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G4665":"<h1>smaragdos</h1>\n<p>Strong n° 4665 <i>Prononciation [smar'-ag-dos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>une pierre précieuse transparente réputée spécialement pour sa couleur verte lumineuse</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σμάραγδος, ου (ἡ)</b> <span>[μᾰ]</span> PLAT. <i>Phæd. 110</i> d ; TH. <i>Lap. 4, 23 ;</i> STR. <i>815 ;</i> NONN. <i>D. 5, 178 ; 18, 80 ;</i> HLD. <i>2, 30 ;</i> PHILSTR. <i>770 ; ou</i> σμάραγδος λίθος, HDT. <i>2, 44 ; 3, 41,</i> émeraude, <i>sorte de jaspe vert transparent</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Postér</i>. ὁ σμ. ORPH. <i>Lith. 608</i>.<br><span><b>Étym</b>. <i>cf. sscr</i>. marakatas <i>ou</i> maraktas.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σμαραγδος - σμάραγδος</font>\n<br><br>dérivation incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G4666":"<h1>smurna</h1>\n<p>Strong n° 4666 <i>Prononciation [smoor'-nah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>myrrhe, une résine amère et un parfum coûteux qui sont extraits d'un arbre ou arbrisseau d'Arabie et d'Ethiopie, par incision dans l'écorce ; également utilisée pour embaumer, en tant qu'antiseptique</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σμύρνα, ης (ἡ)</b> <span>[ᾰ]</span> myrrhe, <i>gomme du myrte d’Arabie,</i> HDT. <i>2, 40, 73, 86, etc. ;</i> HPC. <i>565, 16 ;</i> EUR. <i>Ion 1175 ;</i> AR. <i>Eq. 1332 ;</i> TH. <i>H.P. 9, 1, 2, etc</i>.<br><span><b>Étym</b>. <i>ion. et éol. c</i>. μύρρα, <i>phén</i>. môrâh.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σμυρνα - σμύρνα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G4667":"<h1>Smurna</h1>\n<p>Strong n° 4667 <i>Prononciation [smoor'-nah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Smyrne (Angl. Smyrna) = « myrrhe »\n<ol><li>cité de la côte occidentale de l'Asie Mineure, à 65 km au nord d'Ephèse</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Σμύρνα, ης (ἡ)</b> Smyrna (Smyrne) :<br><b>   I</b> <i>n. géogr. :</i><br><b>      1</b> <i>v. d’Ionie (auj</i>. İzmir) HOM. <i>Ep. 4, 6 ;</i> HDT. <i>1, 14, etc. ;</i><br><b>      2</b> <i>lieu près d’Éphèse ou dans cette ville même,</i> HIPPON. <i>fr. 47 ;</i><br><b>   II</b> <i>n. de f</i>. THÉOD. (PLUT. <i>Parall. min. 22</i>).<br><span><b><span class=\"arrow\"></span></b> <i>épq</i>. Σμύρνη, HOM. <i>l. c. ;</i> THGN. <i>1104, etc</i>.<br><span><b>Étym</b>. Σμύρνα.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Σμυρνα - Σμύρνα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G4668":"<h1>Smurnaios</h1>\n<p>Strong n° 4668 <i>Prononciation [smoor-nah'-yos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>venant de Smyrne, habitant de Smyrne</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Σμυρναῖος, α, ον</b>, de Smyrne <i>en Ionie,</i> PD. <i>fr. 218 ;</i> οἱ Σμ. HDT. <i>1, 143, 150, etc</i>. les habitants de Smyrne.<br><span><b>Étym</b>. Σμύρνα.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Σμυρναιος - Σμυρναῖος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G4669":"<h1>smurnizo</h1>\n<p>Strong n° 4669 <i>Prononciation [smoor-nid'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>être comme la myrrhe</li>\n<li>mélanger et ainsi aromatiser de myrrhe\n<ol type=\"a\">\n<li>vin mêlé de myrrhe : vin parfumé de myrrhe. Les anciens faisaient infuser de la myrrhe dans du vin pour lui donner un goût et une saveur plus agréable</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σμυρνίζω<br>      1 <i>tr.</i></b> préparer avec de la myrrhe, NT. <i>Marc. 15, 23 ;</i><br><b>      2 <i>intr.</i></b> être semblable à la myrrhe, DIOSC. <i>1, 79</i>.<br><span><b>Étym</b>. σμύρνα.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σμυρνιζω - σμυρνίζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Marc (1)</li>\n</ul>\n</td></tr>\n</table>","G4670":"<h1>Sodoma</h1>\n<p>Strong n° 4670 <i>Prononciation [sod'-om-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Sodome (Angl. Sodom) = « qui brûle »\n<ol><li>une ville détruite par le Seigneur faisant pleuvoir le feu et le soufre sur elle</li>\n<li>métaph. Jérusalem dans <a class=\"ref\" data-r=\"REV11.8\">Apocalypse 11.8</a></li></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Σοδομα</font> &lt; סדום - <font face=\"Georgia\">Σόδομα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n9 fois dans 9 versets de 6 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Luc (2)</li>\n<li>Romains (1)</li>\n<li>2 Pierre (1)</li>\n<li>Jude (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G4671":"<h1>soi</h1>\n<p>Strong n° 4671 <i>Prononciation [soy]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>à toi</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σοί</b>, <i>dat. de</i> .\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σοι - σοί</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Pronom</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n219 fois dans 202 versets de 20 livres bibliques (NT)\n<ul>\n<li>Matthieu (49)</li>\n<li>Marc (25)</li>\n<li>Luc (48)</li>\n<li>Jean (27)</li>\n<li>Actes (22)</li>\n<li>Romains (4)</li>\n<li>1 Corinthiens (1)</li>\n<li>2 Corinthiens (2)</li>\n<li>Galates (1)</li>\n<li>Ephésiens (2)</li>\n<li>1 Timothée (5)</li>\n<li>2 Timothée (4)</li>\n<li>Tite (1)</li>\n<li>Philémon (6)</li>\n<li>Hébreux (2)</li>\n<li>Jacques (1)</li>\n<li>2 Jean (1)</li>\n<li>3 Jean (2)</li>\n<li>Jude (1)</li>\n<li>Apocalypse (15)</li>\n</ul>\n</td></tr>\n</table>","G4672":"<h1>Solomon</h1>\n<p>Strong n° 4672 <i>Prononciation [sol-om-one']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Salomon = « paisible »\n<ol><li>le fils de David et le roi le plus sage et le plus riche qui ait jamais vécu</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Σολομων</font> &lt; שלמה - <font face=\"Georgia\">Σολομών</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n12 fois dans 10 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (5)</li>\n<li>Luc (3)</li>\n<li>Jean (1)</li>\n<li>Actes (3)</li>\n</ul>\n</td></tr>\n</table>","G4673":"<h1>soros</h1>\n<p>Strong n° 4673 <i>Prononciation [sor-os']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une urne ou réceptacle pour conserver les os du mort</li>\n<li>la civière de funérailles ou cercueil sur laquelle les Juifs portaient leur mort jusqu'au lieu d'ensevelissement</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σορός, οῦ (ἡ) :<br>      1</b> urne pour les os <i>ou</i> les cendres des morts, IL. <i>23, 91 ; p. ext</i>. cercueil, HDT. <i>1, 68 ; 2, 78 ;</i> AR. <i>Ach. 691, Lys. 600, etc. ;</i> LUC. <i>Herm. 78 ;</i><br><b>      2</b> <i>fig</i>. vieille femme décrépite, AR. <i>Vesp. 1365 ;</i> MACH. (ATH. <i>580</i> c).<br><span><b>Étym</b>. <i>cf</i>. σωρός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σορος - σορός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G4674":"<h1>sos</h1>\n<p>Strong n° 4674 <i>Prononciation [sos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>ton, à toi ...</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σός, σή, σόν</b>, <i>adj. possess. de la 2<sup>e</sup> pers. du sg</i>. ton, ta ; le tien, la tienne :<br><b>      1</b> <i>au sens act., chez les Att. d’ord. avec l’art. :</i> τὸ σὸν κάρα, ESCHL. <i>Ag. 1615,</i> ta tête ; <i>qqf. sans art. :</i> σὸν δέμας, ESCHL. <i>Ag. 1615,</i> ton corps ; <i>sans art. lorsqu’il s’applique à un objet indéterminé :</i> σὸς ἑταῖρος, PLAT. <i>Lys. 204</i> a, un ami à toi ; <i>en appos. à un autre adj. :</i> ὁ σὸς ὁμώνυμος οὗτος, PLAT. <i>Theæt. 147</i> c, celui-ci, ton homonyme ; <i>accompagné d’un gén. détermin. :</i> τὰ σ' αὐτῆς ἔργα, IL. <i>6, 490,</i> tes propres affaires ; σῷ δ' αὐτῆς κράατι, OD. <i>22, 218,</i> à ta propre tête ; <i>subst</i>. οἱ σοί, ATT. les tiens, tes parents, tes amis ; <i>sans subst</i>. εἰ ἐτεόν γε σός, OD. <i>9, 529,</i> si vraiment je suis ton fils ; τὸ σόν, ce qui te concerne, ton intérêt, SOPH. <i>El. 251, Aj. 1313 ; ou</i> tes desseins, ton projet, SOPH. <i>Aj. 99, 1401, etc. ;</i> τὰ σά, tes biens, tes propriétés, OD. <i>2, 369 ;</i> XÉN. <i>Mem. 2, 3, 12 ; ou</i> tes intérêts, SOPH. <i>Aj. 491, etc. ;</i><br><b>      2</b> <i>au sens pass</i>. σὸς πόθος, OD. <i>11, 202,</i> le regret que tu inspires ; σῇ προμηθίᾳ, SOPH. <i>O.C. 332,</i> par les soins qu’il prend de toi ; εὐνοίᾳ τῇ σῇ, PLAT. <i>Gorg. 486</i> a, par la bienveillance qu’il éprouve pour toi.<br><span><b><span class=\"arrow\"></span></b> <i>Gén. épq</i>. σοῖο, OD. <i>15, 511</i>.<br><span><b>Étym</b>. <i>p</i>. *τϝός, <i>de indo-europ</i>. *t(e)uo-, <i>cf. lat</i>. tuus.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σος - σός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Pronom</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n27 fois dans 24 versets de 7 livres bibliques (NT)\n<ul>\n<li>Matthieu (8)</li>\n<li>Marc (2)</li>\n<li>Luc (4)</li>\n<li>Jean (7)</li>\n<li>Actes (3)</li>\n<li>1 Corinthiens (2)</li>\n<li>Philémon (1)</li>\n</ul>\n</td></tr>\n</table>","G4675":"<h1>sou</h1>\n<p>Strong n° 4675 <i>Prononciation [soo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>ton, tes, ...</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σοῦ, 1</b> <i>gén. de</i> σύ <i>et de</i> σός ; <i>comme gén. de</i> σύ, <i>il est enclitique et peut s’écrire sans accent. ;</i><br><b>2</b> <i>v</i>. σεύω. ;<br><b>3</b> <i>v</i>. σόος².\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σου - σοῦ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Pronom</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n493 fois dans 356 versets de 19 livres bibliques (NT)\n<ul>\n<li>Matthieu (113)</li>\n<li>Marc (41)</li>\n<li>Luc (117)</li>\n<li>Jean (41)</li>\n<li>Actes (63)</li>\n<li>Romains (22)</li>\n<li>1 Corinthiens (3)</li>\n<li>2 Corinthiens (1)</li>\n<li>Galates (2)</li>\n<li>Ephésiens (1)</li>\n<li>1 Timothée (6)</li>\n<li>2 Timothée (6)</li>\n<li>Tite (1)</li>\n<li>Philémon (10)</li>\n<li>Hébreux (11)</li>\n<li>Jacques (3)</li>\n<li>2 Jean (2)</li>\n<li>3 Jean (3)</li>\n<li>Apocalypse (47)</li>\n</ul>\n</td></tr>\n</table>","G4676":"<h1>soudarion</h1>\n<p>Strong n° 4676 <i>Prononciation [soo-dar'-ee-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un mouchoir</li>\n<li>un tissu pour essuyer la transpiration du visage et pour nettoyer le nez et également utilisé pour emmailloter la tête d'un mort</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σουδάριον, ου (τὸ)</b> <span>[ᾱ]</span> = <i>lat</i>. sudārium, suaire, NT. <i>Luc. 19, 20 ;, Joh. 11, 44</i>.<br><span><b><span class=\"arrow\"></span></b> <span>[ᾱ]</span> NONN. <i>Jo. 11, 173 ; dor</i>. σωδάριον, HERMIPP. (<i>Com. fr. 2, 416</i>).</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σουδαριον - σουδάριον</font>\n<br><br>origine : Latin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 3 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Jean (2)</li>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4677":"<h1>Sousanna</h1>\n<p>Strong n° 4677 <i>Prononciation [soo-san'-nah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Susanne (Angl. Susanna) = « un lis »\n<ol><li>une des femmes qui assistaient Jésus de leurs biens</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Σουσαννα</font> &lt; שושנה - <font face=\"Georgia\">Σουσάννα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G4678":"<h1>sophia</h1>\n<p>Strong n° 4678 <i>Prononciation [sof-ee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>sagesse, largeur et plénitude de l'intelligence; mot utilisé pour la connaissance, le savoir, de manières très diverses\n<ol type=\"a\">\n<li>la sagesse qui appartient aux hommes\n<ol>\n<li>spéc. la connaissance variée des choses humaines et divines, acquise par la vivacité et l'expérience, et accumulée dans les maximes et proverbes</li>\n<li>la science et l'érudition</li>\n<li>le fait d'interpréter les songes et de toujours donner l'avis le plus sage</li>\n<li>l'intelligence démontrée par la découverte du sens de chiffres mystérieux, ou d'une vision</li>\n<li>adresse dans la direction des affaires</li>\n<li>prudence dévote et convenable dans les relations avec ceux qui ne sont pas disciples de Christ, adresse et discrétion dans la communication de la vérité Chrétienne</li>\n<li>la connaissance et la pratique de ce qui est nécessaire pour une vie juste et pieuse</li>\n</ol>\n</li>\n<li>suprême intelligence, telle qu'elle appartient à Dieu\n<ol>\n<li>à Christ</li>\n<li>la sagesse de Dieu démontrée dans la formulation et l'exécution de ses conseils dans la formation et le gouvernement du monde et des écritures</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σοφία, ας (ἡ) :<br>   I</b> habileté manuelle, <i>particul. :</i><br><b>      1</b> <i>dans les arts manuels ou mécaniques,</i> IL. <i>15, 412 ; en part. d’Hèphæstos et d’Athèna,</i> PLAT. <i>Prot. 321</i> d ; <i>de Dédale et de Palamède,</i> XÉN. <i>Mem. 4, 2, 33 ;</i><br><b>      2</b> <i>dans l’art de jouer de la lyre, de la flûte, etc</i>. HH. <i>Merc. 483 ;</i><br><b>      3</b> <i>p. ext. en parl. de poésie,</i> PD. <i>O. 1, 187 ;</i> XÉN. <i>An. 1, 2, 8, etc. ;</i><br><b>   II</b> savoir, science, PLAT. <i>Rsp. 360</i> d, <i>365</i> d, <i>etc. ; particul</i>. la science des causes, la philosophie, ARSTT. <i>Nic. 6, 7 ; Metaph. 1, 1, 17, etc. ; rar. en ce sens au plur</i>. PD. <i>O. 9, 161 ;</i><br><b>   III</b> sagesse pratique, THGN. <i>1074 ;</i> HDT. <i>1, 30, 60, etc. ; d’où :</i><br><b>      1</b> sagesse <i>en gén</i>. THGN. <i>790, 876 ;</i> SOPH. <i>O.R. 504 ; p. opp. à</i> τὸ σοφόν, l’habileté, l’esprit de ruse, EUR. <i>Bacch. 393, etc. ;</i><br><b>      2</b> <i>en mauv. part,</i> habileté, ruse, HDT. <i>1, 68 ;</i> PD. <i>O. 9, 57, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. σοφίη, HOM. HDT. THGN. <i>ll. cc</i>.<br><span><b>Étym</b>. σοφός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σοφια - σοφία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td>Comparer : , \n<br><br> indique la connaissance par elle-même,  la sagesse qui est montrée dans l'action,  s'applique principalement à l'appréhension des vérités,  ajoute la puissance du raisonnement et renforce leurs parentés.\n<br><br>Comparer : , , \n<br><br> - dénote une « excellence mentale du plus haut niveau »\n<br><br> - critique, incluant le maintien des choses\n<br><br> - pratique, suggérant des lignes d'action</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n51 fois dans 49 versets de 12 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Marc (1)</li>\n<li>Luc (6)</li>\n<li>Actes (4)</li>\n<li>Romains (1)</li>\n<li>1 Corinthiens (17)</li>\n<li>2 Corinthiens (1)</li>\n<li>Ephésiens (3)</li>\n<li>Colossiens (6)</li>\n<li>Jacques (4)</li>\n<li>2 Pierre (1)</li>\n<li>Apocalypse (4)</li>\n</ul>\n</td></tr>\n</table>","G4679":"<h1>sophizo</h1>\n<p>Strong n° 4679 <i>Prononciation [sof-id'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>rendre sage, enseigner</li>\n<li>devenir sage, avoir de la compréhension\n<ol type=\"a\">\n<li>inventer, jouer le « sophiste » (celui qui développe des raisonnements faux, ayant l'apparence de la logique)</li>\n<li>tramer habilement ou avec ruse</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σοφίζω</b> <span>(<i>f. inus., ao</i>. ἐσόφισα, <i>pf. inus. ; pass. f</i>. σοφισθήσομαι, <i>ao</i>. ἐσοφίσθην, <i>pf</i>. σεσόφισμαι)</span><br><b>      1</b> rendre sage <i>ou</i> habile, <i>acc</i>. SPT. <i>Ps. 19, 7 ;</i> NT. <i>2Tim. 3, 15 ; d’où au pass</i>. devenir habile, expérimenté, XÉN. <i>Mem. 1, 2, 46 ;</i> PLAT. <i>Hipp. ma. 283</i> a ; σεσοφισμένος, η, ον, expérimenté, habile, PHOCYL. <i>122 ;</i> τινος, HÉS. <i>O. 647 ;</i> ἔν τινι, XÉN. <i>Cyn. 13, 6,</i> en qqe ch. ;<br><b>      2</b> faire <i>ou</i> imaginer avec ruse, SOPH. <i>Ph. 77 ;</i><br><b><i>Moy</i>. σοφίζομαι</b> <span>(<i>f</i>. -ίσομαι, <i>ao</i>. ἐσοφισάμην, <i>pf</i>. σεσόφισμαι)</span> agir <i>ou</i> parler en sophiste, <i>càd</i>. user d’arguments sophistiques <i>ou</i> de moyens frauduleux :<br><b>      1</b> <i>abs</i>. THGN. <i>19 ;</i> EUR. <i>I.A. 744 ;</i> DÉM. <i>303, 19, etc. ;</i> τινι, EUR. <i>Bacch. 200 ;</i> περί τι, PLAT. <i>Rsp. 509</i> d ; πρός τι, POL. <i>6, 58, 12,</i> au sujet <i>ou</i> en vue de qqn <i>ou</i> de qqe ch. ; σ. πρὸς τὸν νόμον, PLUT. <i>Dem. 27,</i> agir frauduleusement à l’égard de la loi ;<br><b>      2</b> <i>avec un acc. de chose :</i> σ. τι, HDT. <i>1, 80 ; etc. ;</i> AR. <i>Nub. 547, etc.,</i> imaginer habilement qqe ch. ; τί τινι, EUR. <i>Bacch. 200 ;</i> τι πρός τινα, ARSTT. <i>Pol. 4, 10, 6,</i> ruser en qqe ch. avec qqn ; <i>p. suite, au sens trans</i>. sophistiquer, teindre (les cheveux) <i>acc</i>. CLÉM. <i>262 ;</i> altérer (la vérité) CLÉM. <i>549 ;</i> frauder (la loi) PHILSTR. <i>92, etc. ;</i><br><b>      3</b> <i>avec un acc. de pers. :</i> σ. τινα, ANTH. <i>12, 25,</i> tromper qqn.<br><span><b><span class=\"arrow\"></span></b> <i>Pf. pass. au sens pass</i>. HÉS. <i>O. 647 ;</i> PHOCYL. <i>122 ; au sens moy</i>. DÉM. <i>853, 5 ; pl.q.pf. au sens moy. 3 sg</i>. ἐσεσόφιστο, HDT. <i>1, 80</i>.<br><span><b>Étym</b>. σοφός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σοφιζω - σοφίζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>2 Timothée (1)</li>\n<li>2 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G4680":"<h1>sophos</h1>\n<p>Strong n° 4680 <i>Prononciation [sof-os']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>sage\n<ol type=\"a\">\n<li>habile, expert : d'artificiers</li>\n<li>sage, habile dans les lettres, cultivé, instruit\n<ol>\n<li>des philosophes et orateurs Grecs</li>\n<li>des théologiens Juifs</li>\n<li>des enseignants chrétiens</li>\n</ol>\n</li>\n<li>qui forme le meilleur projet et utilise les meilleurs moyens pour leur exécution</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σοφός, ή, όν :<br>   I</b> habile, <i>particul. dans les arts mécaniques,</i> PD. <i>P. 5, 154, etc. ;</i> ESCHL. <i>Suppl. 770 ;</i> PLAT. <i>Virt. 376</i> a, <i>etc. ; d’où</i> habile, <i>en gén. en parl. de poètes,</i> PLAT. <i>Phædr. 235</i> a, <i>etc. ; de devins,</i> ESCHL. <i>Sept. 382 ;</i> SOPH. <i>O.R. 484 ; de médecins,</i> SOPH. <i>Aj. 581 ;</i> PLAT. <i>Leg. 761</i> d, <i>etc. ;</i> τι, PLAT. <i>Phil. 17</i> c, <i>etc. ;</i> περί τι, PLAT. <i>Conv. 203</i> a, <i>Pol. 290</i> b, <i>etc. ;</i> περί τινος, PLAT. <i>Ap. 19</i> c ; ἔν τινι, EUR. <i>I.T. 1238 ;</i> εἴς τι, EUR. <i>fr. 162, 3, etc. ;</i> πρός τι, HDN <i>3, 5, 9, etc</i>. en qqe ch. ; <i>avec un inf</i>. PD. <i>P. 8, 104 ;</i> SOPH. <i>fr. 470 ;</i> PLAT. <i>Phædr. 266</i> c, <i>etc</i>. habile à, <i>etc. ;</i><br><b>   II</b> <i>en parl. de l’intelligence ou du caractère :</i><br><b>      1</b> prudent, sage, PD. <i>O. 11, 10, etc. ;</i> SOPH. <i>Ph. 431, etc. ;</i> PLAT. <i>Ap. 20</i> c, <i>etc. ; en parl. de choses (cœur, esprit, nature, etc</i>.) ESCHL. <i>Pr. 1037, etc. ;</i> SOPH. <i>El. 474, 1016 ;</i> XÉN. <i>Conv. 1, 6 ;</i> PLAT. <i>Prot. 312</i> c, <i>etc. ;</i> PLUT. <i>M. 225</i> c, <i>etc. ;</i> τὸ σοφόν, PLAT. <i>Rsp. 502</i> d, <i>etc. ;</i> τὰ σοφά, EUR. <i>I.A. 1214, etc</i>. la sagesse ; σοφόν ἐστι, <i>avec l’inf</i>. il est sage de, <i>etc</i>. EUR. <i>Hec. 228 ;</i><br><b>      2</b> <i>particul</i>. initié à la sagesse, savant, instruit, <i>particul. en parl. de philosophes,</i> HDT. <i>2, 49 ;</i> XÉN. <i>Mem. 2, 1, 11 ;</i> PLAT. <i>Prot. 339</i> b, <i>etc. ;</i> οἱ ἑπτὰ σοφοί, DICÉARQ. (DL. <i>1, 40</i>) les sept sages ; <i>ironiq</i>. subtil, profond, <i>d’où</i> obscur : τὸ σοφὸν οὐ σοφία, EUR. <i>Bacch. 393,</i> ce qui est trop ingénieux n’est plus la sagesse ; οὐδὲν ποικίλον οὐδὲ σοφόν, DÉM. <i>120, 21,</i> rien de subtil ni de savant, rien qui demande une intelligence souple ni profonde ;<br><b>      3</b> <i>particul</i>. ingénieux, fin, rusé, SOPH. <i>Ph. 431, etc. ;</i> τὰ σοφά, SOPH. <i>Ph. 1244,</i> l’habileté, la finesse.<br><span>•<i> Cp</i>. σοφώτερος, ATT. (EUR. <i>Med. 675, etc</i>.) ; PLUT. <i>M. 15</i> d ; <i>sup</i>. σοφώτατος, PD. <i>N. 5, 32 ; Att</i>. (SOPH. <i>fr. 380, etc</i>.).<br><span><b>Étym</b>. <i>obscure, p.-ê. pré-grec</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σοφος - σοφός</font>\n<br><br>parent de saphes (clair)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td> – dénote le sage, celui qui est habile, un expert\n<br><br> – « intelligent », celui qui peut assembler des choses, qui a perspicacité et compréhension\n<br><br> – « prudent », celui qui a d'abord des perceptions rapides et correctes, de là, « discret, circonspect »</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n21 fois dans 20 versets de 7 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Luc (1)</li>\n<li>Romains (4)</li>\n<li>1 Corinthiens (11)</li>\n<li>Ephésiens (1)</li>\n<li>1 Timothée (1)</li>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G4681":"<h1>Spania</h1>\n<p>Strong n° 4681 <i>Prononciation [span-ee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Espagne (Angl. Spain) = « rare, précieux »\n<ol><li>toute la péninsule au sud des Pyrénées</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Σπανια - Σπανία</font>\n<br><br>probablement d'origine étrangère</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Romains (2)</li>\n</ul>\n</td></tr>\n</table>","G4682":"<h1>sparasso</h1>\n<p>Strong n° 4682 <i>Prononciation [spar-as'-so]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>convulser, bouleverser, déchirer, malmener, secouer</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σπαράσσω</b>, <i>att</i>. <b>σπαράττω</b> <span>(<i>ao</i>. ἐσπάραξα, <i>pf. inus. ; pass. ao</i>. ἐσπαράχθην)</span> <span>[πᾰ]</span><br><b>      1 <i>tr.</i></b> déchirer, <i>en parl. de chiens, d’animaux en gén</i>. EUR. <i>Med. 1217 ;</i> AR. <i>Ran. 424 ; en parl. de la foudre,</i> ESCHL. <i>Pr. 1018 ; fig</i>. AR. <i>Ach. 688 ;</i> PLAT. <i>Rsp. 539</i> b ; DÉM. <i>785, 18 ; au pass</i>. SPT. <i>3Macc. 4, 6 ; Jer. 4, 19 ; p. suite,</i> saisir comme pour arracher : κόμης, EUR. <i>I.A. 1459,</i> par les cheveux ;<br><b>      2 <i>intr.</i></b> palpiter, être agité convulsivement, <i>d’où</i> faire des efforts convulsifs, HPC. <i>207</i> h.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σπαρασσω - σπαράσσω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 2 livres bibliques (NT)\n<ul>\n<li>Marc (3)</li>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G4683":"<h1>sparganoo</h1>\n<p>Strong n° 4683 <i>Prononciation [spar-gan-o'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>envelopper dans des langes\n<ol type=\"a\">\n<li>d'un enfant qui vient de naître</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σπαργανόω-ῶ</b> <span>[γᾰ]</span> envelopper de langes, emmailloter, EUR. <i>Ion 955 ;</i> ARSTT. <i>H.A. 7, 4, 10 ; au pass</i>. HPC. <i>Aër. 292, 766</i> c ; NT. <i>Luc. 2, 12 ; fig</i>. SOTAD. (<i>Com. fr. 3, 586</i>) ; PLUT. <i>M. 691</i> c.<br><span><b>Étym</b>. σπάργανον.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σπαργανοω - σπαργανόω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Luc (2)</li>\n</ul>\n</td></tr>\n</table>","G4684":"<h1>spatalao</h1>\n<p>Strong n° 4684 <i>Prononciation [spat-al-ah'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>vivre dans un grand luxe, mener une vie de volupté, s'adonner au plaisir</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σπαταλάω-ῶ</b> <span>[ᾰᾰ]</span><br><b>      1</b> vivre dans les délices, POL. <i>Exc. Vat. p. 451 ;</i> SPT. <i>Sir. 21, 15 ;</i> NT. <i>1Tim. 5, 6 ;</i><br><b>      2</b> être efféminé, THÉANO <i>Ep. 1</i>.<br><span><b>Étym</b>. σπατάλη.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σπαταλαω - σπαταλάω</font>\n<br><br>vient de spatale (luxe)\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>1 Timothée (1)</li>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G4685":"<h1>spao</h1>\n<p>Strong n° 4685 <i>Prononciation [spah'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>tirer</li>\n<li>tirer l'épée, dégainer</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σπάω-ῶ</b> <span>(<i>f</i>. άσω <span>[ᾰ]</span>, <i>ao</i>. ἔσπασα <span>[ᾰ]</span>, <i>pf</i>. ἔσπακα <span>[ᾰ]</span>, <i>pass. ao</i>. ἐσπάσθην, <i>pf</i>. ἔσπασμαι)</span><br><b>   I</b> tirer, <i>particul. :</i><br><b>      1</b> tirer hors, retirer, attirer, extraire : ἔγχος, IL. <i>11, 458 ;</i> ξίφος, SOPH. <i>O.R. 1148,</i> tirer une javeline, une épée ; ἐσπασμένοις τοῖς ξίφεσι, DS. <i>4, 52,</i> avec les épées tirées ; <i>fig</i>. σπ. ῥίζαν τινός, LYC. <i>623,</i> tirer son origine de qqn, descendre de qqn ; τὴν κλῆσιν ἀπό τινος, SEXT. <i>M. 1, 46,</i> tirer son nom de qqn <i>ou</i> de qqe ch. ;<br><b>      2</b> attirer, tirer à soi : <i>proverb</i>. ἡ μήρινθος οὐδὲν ἔσπασεν, AR. <i>Th. 928,</i> cette ligne n’attira pas ; οὐκ ἔσπασε ταύτῃ γε, AR. <i>Vesp. 175,</i> cela ne prit pas, ne réussit pas ; <i>particul. en parl. de liquides,</i> humer, boire à longs traits, EUR. <i>Cycl. 571 ;</i> ARSTT. <i>H.A. 8, 6 ;</i> EL. <i>N.A. 6, 51 ; avec l’acc</i>. EUR. <i>Cycl. 417, 573, etc. ; p. opp. à</i> λάπτειν, PLUT. <i>M. 699</i> d ; σπ. πνεῦμα, ARSTT. <i>Respir. 5 ;</i> ἀέρα, ARÉT. <i>40, 34,</i> humer l’air ; <i>avec le gén</i>. ἀκράτου, ATH. <i>613</i> a, humer du vin pur ; <i>en parl. de mets,</i> dévorer, engloutir, avaler, <i>acc</i>. ESCHL. <i>Ch. 533 ;</i> LYC. <i>476 ;</i> DIPH. (ATH. <i>132</i> d) ; <i>avec le gén</i>. ARSTT. <i>H.A. 9, 6 ; p. anal</i>. σπ. ὕπνον, PHILSTR. <i>V. soph. p. 591 ;</i> ὕπνου, HLD. <i>4, 1, p. 173Cor</i>. humer le sommeil, jouir du sommeil ; σπ. φαντάσματα ὀνείρων, JOS. <i>B.J. 3, 8, 3,</i> avoir des visions pendant des songes ; <i>fig. au sens mor</i>. attirer, diriger, conduire, séduire, <i>en parl. des passions,</i> PLAT. <i>Leg. 644</i> c ; <i>de la parole qui persuade,</i> SOPH. <i>El. 567 ;</i><br><b>      3</b> tirailler : ἵππον, XÉN. <i>Eq. 7, 1,</i> ἵππου στόμα, XÉN. <i>Eq. 9, 5,</i> un cheval, la bouche d’un cheval ; κόμην, SOPH. <i>O.R. 1243,</i> arracher la chevelure ; <i>avec un adv. de lieu :</i> ἐσπᾶτο πέδονδε καὶ μετάρσιος, SOPH. <i>Tr. 786,</i> il se roulait à terre, puis se relevait ; <i>avec une prép. :</i> σπ. ἀπό <i>et le gén</i>. EUR. <i>Hec. 89 ;</i> ἐκ <i>et le gén</i>. EUR. <i>Hec. 407 ;</i> παρά <i>et le gén</i>. PLAT. <i>Leg. 666</i> e, tirer violemment de, arracher de, <i>etc. ;</i><br><b>      4</b> <i>p. suite,</i> déchirer, lacérer, déchiqueter, <i>en parl. de bêtes féroces,</i> SOPH. <i>Ant. 258, 1003 ;</i> EUR. <i>I.A. 777 ;</i><br><b>      5</b> arracher de force, <i>acc</i>. HPC. <i>453, 13, etc. ;</i><br><b>      6</b> disloquer, arracher en tiraillant : τὸ σκέλος, PLUT. <i>Arat. 33,</i> la jambe ; <i>au pass</i>. se luxer (la jambe, le pied, <i>etc</i>.) HDT. <i>6, 134 ;</i> EUR. <i>Cycl. 639 ;</i><br><b>      7</b> occasionner des mouvements nerveux <i>ou</i> des attaques nerveuses, <i>d’où au pass</i>. souffrir d’attaques nerveuses, ARSTT. <i>H.A. 6, 22 ;</i> TH. <i>H.P. 4, 4, 13 ;</i> DIOSC. <i>3, 19, etc. ;</i><br><b>      8</b> <i>fig</i>. tirailler ; <i>au pass</i>. être tourmenté par des soucis, ARR. <i>Epict. 1, 1, 16 ;</i><br><b><i>Moy.</i></b> <span>(<i>f</i>. σπάσομαι <span>[ᾰ]</span>, <i>ao</i>. ἐσπασάμην <span>[ᾰᾰ]</span>, <i>pf</i>. ἔσπασμαι)</span> tirer à soi, <i>particul. :</i><br><b>      1</b> tirer à soi hors de, <i>acc</i>. OD. <i>10, 166, etc. ;</i> φάσγανον, OD. <i>22, 74,</i> tirer son épée ; τὰ ξίφη, XÉN. <i>An. 7, 4, 16, etc</i>. tirer les épées ; ἄορ παρὰ μηροῦ, IL. <i>16, 473 ;</i> OD. <i>10, 439, etc</i>. tirer son épée du fourreau le long de la cuisse ; ἔγχος ἐκ σύριγγος, IL. <i>19, 387,</i> tirer sa javeline de son étui, <i>etc. ;</i><br><b>      2</b> aspirer, humer, <i>acc</i>. APD. <i>1, 9, 27, etc. ; fig</i>. ὕπνον, HLD. <i>2, 16,</i> humer le sommeil ; <i>d’où</i> absorber, avaler, <i>acc</i>. LYC. <i>607</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Act. ao. inf. ion</i>. σπῆσαι, ARÉT. <i>46 dout. Moy. ao. poét</i>. ἐσπασσάμην, IL. <i>11, 240, etc. ;</i> OD. <i>11, 231 ; pf. au sens moy</i>. ἔσπασμαι, XÉN. <i>An. 7, 4, 16 ; Cyr. 7, 5, 29</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *(s)peh₂-, tirer.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σπαω - σπάω</font>\n<br><br>un verbe primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4686":"<h1>speira</h1>\n<p>Strong n° 4686 <i>Prononciation [spi'-rah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>toute chose enroulée en cercle ou en boule, enroulé, choses reliées ensemble</li>\n<li>une cohorte militaire\n<ol type=\"a\">\n<li>la dixième partie d'une légion\n<ol>\n<li>à peu près 600 hommes c.à.d. des légionnaires</li>\n<li>en auxiliaires : de 500 à 1000</li>\n<li>un « manipule », ou la trentième partie d'une légion</li>\n</ol>\n</li>\n<li>toute bande, compagnie, ou détachement, de soldats</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σπείρα</b> <i>ou mieux</i> <b>σπεῖρα, ας (ἡ)</b> enroulement, <i>d’où :</i><br><b>   I</b> spirale, repli tortueux d’un serpent, <i>d’ord. au plur</i>. SOPH. <i>fr. 480 Dind. ; au sg</i>. NIC. <i>Th. 156, 179 ;</i> EUR. <i>Med. 481 ; d’où</i> serpent enroulé, A. RH. <i>4, 151 ;</i> ARAT. <i>47, 89 ;</i> DS. <i>3, 37 ;</i><br><b>   II</b> objet enroulé, entortillé :<br><b>      1</b> replis d’un filet, SOPH. <i>Ant. 347 ;</i><br><b>      2</b> cordage, NIC. (ATH. <i>683</i> c) ; HPC. <i>685, 10 ; spécial</i>. cordage qu’on enroulait pour ralentir la marche d’un navire dans une tempête, PLUT. <i>M. 507</i> a ; LUC. <i>Tox. 19 ;</i><br><b>      3</b> veine en forme de spirale dans le bois, TH. <i>H.P. 5, 2, 3 ;</i><br><b>      4</b> base d’une colonne, VITR. <i>3, 41 ;</i><br><b>      5</b> sorte de gâteau, CHRYSIPP. (ATH. <i>647</i> d) ;<br><b>      6</b> bourrelet rond, coussin posé sur le haut de la tête pour porter des fardeaux, APD. <i>2, 5, 11 ;</i><br><b>      7</b> ceste, <i>lanière de cuir que les athlètes s’enroulaient autour des poignets pour le pugilat,</i> THCR. <i>Idyl. 22, 80 ;</i><br><b>   III</b> corps de troupes, POL. <i>2, 3, 2 ; 15, 9, 9 ;</i> NT. <i>Ap. 27, 1 ; particul. traduct. du lat</i>. manipulus, compagnie (⅓ de la cohorte) POL. <i>11, 23, 1, etc. ; ou qqf. du lat</i>. cohors, cohorte, NT. <i>Ap. 10, 1 ;</i> σπείρα στρατηγίς, PLUT. <i>Ant. 39,</i> la cohorte prétorienne.<br><span><b><span class=\"arrow\"></span></b> <i>Ion. et épq</i>. σπείρη, HPC. NIC. <i>ll. cc</i>.<br><span><b>Étym</b>. <i>p.-ê. R. indo-europ</i>. *sper-, tourner, enrouler ; <i>cf</i>. σπάρτον, σπεῖρον.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σπειρα - σπεῖρα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n7 fois dans 7 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Jean (2)</li>\n<li>Actes (3)</li>\n</ul>\n</td></tr>\n</table>","G4687":"<h1>speiro</h1>\n<p>Strong n° 4687 <i>Prononciation [spi'-ro]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>semer, éparpiller, semence, graine</li>\n<li>métaph. de dires proverbiaux</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σπείρω</b> <span>(<i>f</i>. σπερῶ, <i>ao</i>. ἔσπειρα, <i>pf</i>. ἔσπαρκα ; <i>pass. ao.2</i> ἐσπάρην <span>[ᾰ]</span> <i>pf</i>. ἔσπαρμαι)</span><br><b>   I</b> semer, HÉS. <i>O. 389, etc. ;</i> κέγχρους, HÉS. <i>Sc. 399 ;</i> στάχυν, EUR. <i>Cycl. 121, etc</i>. du millet, du blé, <i>etc. ;</i> σῖτον, καρπόν, HDT. <i>3, 100 ; 4, 17,</i> du blé, des graines de fruit ; <i>fig. p. opp. à</i> θερίζειν, PLAT. <i>Phædr. 260</i> d ; ARSTT. <i>Rhet. 3, 3, 4 ;</i> NT. <i>Gal. 6, 7 ; 1Cor. 9, 11 ;</i> σπ. καινοτάταις διανοίαις, AR. <i>Vesp. 1044,</i> semer des idées nouvelles, <i>en parl. de nouvelles créations poétiques ;</i> σπ. (τὸ σπέρμα) μέλανι διὰ καλάμου, PLAT. <i>Phædr. 276</i> c, répandre (des semences, <i>càd</i>. des pensées) avec de l’encre par le moyen du roseau à écrire ; σπ. εἰς ἀρετῆς ἔκφυσιν, PLAT. <i>Leg. 777</i> c, répandre de la semence de vertu, <i>litt</i>. pour faire lever la vertu ; <i>p. suite :</i><br><b>      1</b> ensemencer : ἄρουραν, HÉS. <i>O. 461 ;</i> γῆν, HDT. <i>4, 42,</i> un champ, une terre ; <i>cf</i>. XÉN. <i>Ages. 1, 20 ; Cyr. 8, 3, 38 ;</i> σπ. πόντον, THGN. <i>106,</i> ensemencer la mer, <i>en parl. d’efforts infructueux ; fig. en parl. de la génération :</i> σπ. ἄρουραν, ESCHL. <i>Sept. 754 ;</i> λέχη, EUR. <i>Ion 64 ;</i> τέκνων ἄλοκα, EUR. <i>Ph. 18,</i> ensemencer le champ, la couche, le sillon, d’où naîtront les enfants ;<br><b>      2</b> engendrer, produire, SOPH. <i>Tr. 33 ;</i> PLAT. <i>Leg. 775</i> d ; <i>avec un acc</i>. SOPH. <i>Aj. 1293 ;</i> EUR. <i>Hipp. 449, etc. ; au pass</i>. SOPH. <i>O.R. 1498 ;</i> PLAT. <i>Leg. 839</i> a, <i>etc. ;</i><br><b>   II</b> répandre comme de la semence, <i>d’où :</i><br><b>      1</b> saupoudrer : σπ. τινὰ ἅλας, SPT. <i>Judith 9, 45,</i> répandre du sel sur qqn ;<br><b>      2</b> disséminer, éparpiller : χρυσόν, HDT. <i>7, 107,</i> de l’or ; φλόγα, POÈT. (ARSTT. <i>Poet. 21, 14</i>) faire jaillir une flamme ; δρόσον, EUR. <i>Andr. 167,</i> répandre de l’eau en aspergeant ; <i>au pass</i>. être répandu, disséminé, <i>en parl. d’armes répandues sur le sol,</i> EUR. <i>H.f. 1098 ; en parl. de pers</i>. être répandu : κατὰ τὴν Ἑλλάδα, THC. <i>2, 27,</i> à travers la Grèce ; εἰς ἁρπαγήν, XÉN. <i>Hell. 3, 4, 22,</i> pour piller ; <i>fig</i>. répandre des paroles, AR. <i>Ran. 1206, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ao. itér</i>. σπείρεσκον, HDT. <i>4, 42</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *sper-, répandre ; <i>cf. degré normal :</i> σπέρμα ; <i>degré fléchi :</i> σπόρος ; <i>degré zéro : ao.2 pass</i>. ἐσπάρην, <i>pf</i>. ἔσπαρκα, <i>vb</i>. σπαρτός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σπειρω - σπείρω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n54 fois dans 42 versets de 8 livres bibliques (NT)\n<ul>\n<li>Matthieu (19)</li>\n<li>Marc (12)</li>\n<li>Luc (6)</li>\n<li>Jean (2)</li>\n<li>1 Corinthiens (8)</li>\n<li>2 Corinthiens (3)</li>\n<li>Galates (3)</li>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G4688":"<h1>spekoulator</h1>\n<p>Strong n° 4688 <i>Prononciation [spek-oo-lat'-ore]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un espion, un éclaireur</li>\n<li>sous les empereurs un serviteur et membre du corps de garde, employé comme messager, veilleur, et comme chargé des exécutions</li>\n<li>le nom est donné à un serviteur d'Hérode Antipas qui a agi comme un bourreau</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σπεκουλάτωρ, ορος (ὁ)</b> = <i>lat</i>. speculator, <i>soldat chargé de la garde des prisonniers,</i> NT. <i>Marc. 6, 27</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σπεκουλατωρ - σπεκουλάτωρ</font>\n<br><br>origine : Latin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Marc (1)</li>\n</ul>\n</td></tr>\n</table>","G4689":"<h1>spendo</h1>\n<p>Strong n° 4689 <i>Prononciation [spen'-do]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>verser comme une boisson d'offrande, faire une libation</li>\n<li>dans le N.T. être offert comme une libation</li>\n<li>fig. utilisé de quelqu'un dont le sang est versé dans une mort violente pour la cause de Dieu</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σπένδω</b> <span>(<i>f</i>. σπείσω, <i>ao</i>. ἔσπεισα, <i>pf. inus. ; pf. pass</i>. ἔσπεισμαι)</span><br><b>      1</b> verser en forme de libation, faire une libation, <i>abs</i>. IL. <i>9, 177 ;</i> OD. <i>3, 45 ;</i> SOPH. <i>Ph. 1033 ;</i> XÉN. <i>Cyr. 7, 1, 1, etc. ;</i> PLAT. <i>Leg. 799</i> b, <i>etc. ;</i> τινί, IL. <i>6, 259 ; 16, 227 ;</i> OD. <i>3, 334 ; 4, 591, etc. ;</i> AR. <i>Eq. 221 ;</i> PLUT. <i>M. 164</i> d, en l’honneur d’un dieu ; (οἶνον, IL. <i>11, 775 ;</i> OD. <i>18, 151 ; avec le dat. :</i> ὕδατι, OD. <i>12, 363 ; postér. avec le gén</i>. οἶνου, HDN <i>5, 5, 12,</i> offrir en libation du vin, de l’eau, <i>etc</i>. faire une libation de vin, d’eau, <i>etc</i>.) ; λοιϐάς, SOPH. <i>El. 270 ;</i> σπονδάς, EUR. <i>El. 512 ;</i> χοάς, EUR. <i>Or. 1322,</i> faire des libations ; <i>avec le dat. d’instrument :</i> δέπαϊ, IL. <i>23, 196 ;</i> OD. <i>7, 137,</i> avec une coupe ;<br><b>      2</b> verser comme pour une libation (des larmes, du sang, <i>etc.) acc</i>. ANTH. <i>7, 555 ; 9, 184 ; fig. en parl. de pers</i>. σπένδομαι, NT. <i>Phil. 2, 17,</i> je m’offre en sacrifice ;<br><b>      3</b> <i>particul</i>. consacrer par une libation (un traité, une convention, <i>etc.), d’où au pass</i>. être conclu, <i>en parl. d’une convention,</i> THC. <i>3, 111 ; 4, 46 ;</i> PLUT. <i>Rom. 19 ;</i><br><b><i>Moy.</i></b> <span>(<i>f</i>. σπείσομαι, <i>ao</i>. ἐσπεισάμην, <i>pf</i>. ἔσπεισμαι)</span> consacrer par une libation : εἰρήνην, HDT. <i>7, 148 ;</i> THC. <i>3, 24, etc</i>. un traité de paix ; <i>d’où en gén</i>. conclure un arrangement :<br><b>      1</b> <i>abs</i>. HDT. <i>3, 144 ;</i> THC. <i>4, 119 ;</i> XÉN. <i>An. 7, 5, 23, etc. ;</i> σπ. σπονδάς, THC. <i>8, 57 ;</i> XÉN. <i>An. 4, 1, 1 ;</i> LUC. <i>Tim. 43,</i> conclure un traité, un arrangement ; τινί, THC. <i>5, 5 ;</i> XÉN. <i>An. 1, 9, 7, etc. ;</i> AR. <i>Ach. 225, etc. ;</i> πρός τινα, THC. <i>5, 17, 30 ;</i> XÉN. <i>An. 3, 5, 16 ;</i> PLUT. <i>Thes. 19 ;</i> μετά τινος, THC. <i>3, 109,</i> avec qqn ; <i>ou avec le dat. de la pers. pour laquelle on conclut une convention,</i> XÉN. <i>An. 2, 3, 7 ; de même</i> σπ. τῇ πρεσϐείᾳ, ESCHN. <i>62, 39,</i> donner un sauf-conduit pour l’ambassade, accorder un sauf-conduit aux ambassadeurs ;<br><b>      2</b> <i>avec l’acc. de la chose, au sujet de laquelle on stipule :</i> νεῖκος, EUR. <i>Med. 1140,</i> arranger une querelle ; πόλεμον, DH. <i>9, 36,</i> terminer une guerre ; ἀναχώρησιν, THC. <i>3, 109,</i> stipuler le droit de se retirer ;<br><b>      3</b> <i>avec</i> ἐπί <i>et le dat</i>. EUR. <i>Ph. 1240 ;</i> XÉN. <i>An. 4, 4, 6,</i> conclure un arrangement à la condition de <i>ou</i> que, <i>etc. ;</i><br><b>      4</b> <i>avec un inf. seul,</i> THC. <i>3, 109 ; 4, 114, etc. ; ou précédé soit de</i> ἦ μήν, THC. <i>4, 118 ; soit de</i> ὥστε, THC. <i>6, 7</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Act. prés. sbj. 2 sg</i>. σπένδῃσθα, OD. <i>4, 591. Impf. itér</i>. σπένδεσκον, IL. <i>16, 227 ;</i> OD. <i>7, 138. Impf. itér. 3 sg</i>. σπείσασκε, OD. <i>8, 89. Ao. sbj. 1 pl. épq</i>. σπείσομεν (<i>p</i>. -ωμεν) OD. <i>7, 165, 181</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *spend-, faire une libation ; <i>cf</i>. σπονδή, <i>lat</i>. spondeō.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σπενδω - σπένδω</font>\n<br><br>apparemment un verbe primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Philippiens (1)</li>\n<li>2 Timothée (2)</li>\n</ul>\n</td></tr>\n</table>","G4690":"<h1>sperma</h1>\n<p>Strong n° 4690 <i>Prononciation [sper'-mah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>de ce qui fera germer un plant\n<ol type=\"a\">\n<li>la semence c.à.d. la graine ou noyau qui contient en lui-même le germe de la plante future\n<ol>\n<li>des graines ou noyaux semés</li>\n</ol>\n</li>\n<li>métaph. un noyau c.à.d. un reliquat, ou quelques survivants réservés comme germes d'une nouvelle race (comme la semence qui est conservée à la moisson pour les futures semailles)</li>\n</ol>\n</li>\n<li>le sperme viril\n<ol type=\"a\">\n<li>le produit de cette semence, la descendance, les enfants, la postérité, la progéniture</li>\n<li>la famille, la race, la postérité</li>\n<li>tout ce qui possède la force vitale ou le pouvoir de donner la vie\n<ol>\n<li>de l'énergie du Saint Esprit, agissant dans l'âme, et par lequel nous sommes régénérés</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σπέρμα, ατος (τὸ) :<br>   I</b> semence :<br><b>      1</b> <i>en parl. de plantes,</i> semence, grain, graine, HÉS. <i>O. 444, 469 ;</i> HH. <i>Cer. 307 ;</i> XÉN. <i>Œc. 17, 8 et 10, Cyr. 8, 3, 38 ; particul</i>. fruit propre à la semence <i>ou</i> mûri pour servir à la semence, ANTIPH. (ATH. <i>84</i> b) ; DIOSC. <i>3, 74 ;</i> LGN <i>43, 4 ;</i><br><b>      2</b> <i>en parl. d’animaux ou de pers</i>. semence, germe, PD. <i>N. 10, 151 ;</i> T. LOCR. <i>100</i> a ; XÉN. <i>Mem. 4, 4, 23 ;</i> PLAT. <i>Leg. 839</i> b ; σπέρμα λογικοῦ, SEXT. <i>M. 9, 101,</i> semence <i>ou</i> germe d’un être doué de raison ; <i>avec le gén. de celui qui féconde :</i> σπ. θεοῦ φέρειν, PD. <i>P. 3, 27,</i> être enceinte d’un dieu ; <i>avec le gén. de l’être engendré :</i> σπ. φέρειν Ἡρακλέους, PD. <i>N. 10, 29,</i> porter le germe d’où naîtra Hèraklès, <i>en parl. de Zeus ;</i> σπέρμα ἔχειν, PD. <i>O. 9, 92 ;</i> δέχεσθαι, PD. <i>P. 4, 452 ;</i> παραλαϐεῖν, EUR. <i>Or. 553,</i> avoir <i>ou</i> recevoir de la semence, <i>càd</i>. être fécondée ; <i>au plur</i>. procréation, SOPH. <i>O.R. 1246, etc. ; en prose,</i> σπέρματος πλῆσαι, PLUT. <i>Lyc. 15,</i> féconder ; <i>p. suite,</i> race, origine, ESCHL. <i>Suppl. 290, etc. ;</i> SOPH. <i>Ant. 982, etc. ;</i> EUR. <i>Hipp. 618 ;</i> σπέρμα σῶν ὁμαιμόνων, SOPH. <i>Tr. 1147,</i> tes frères ; κατ' ἀμφότερα τὰ σπέρματα, HPC. <i>1271, 41,</i> du côté paternel et maternel ;<br><b>      3</b> <i>en gén</i>. germe, principe, cause, origine (du feu) OD. <i>5, 490 ; cf</i>. PD. <i>O. 7, 87 ; P. 3, 66 ;</i> PLAT. <i>Tim. 56</i> b, <i>etc. ;</i> συκοφάντου καὶ πονηροῦ σπέρμα καὶ ῥίζα, DÉM. <i>784, fin,</i> graine et racine de sycophante et de méchant ; σπέρμα κακῶν, DÉM. <i>280, 28,</i> semence de maux ; <i>cf</i>. DÉM. <i>748, 31 ;</i> σπέρμα τῆς στάσεως, PLUT. <i>Mar. 10,</i> semence de guerre civile ;<br><b>   II</b> <i>p. suite,</i> ce qui sort de la semence, <i>d’où :</i><br><b>      1</b> les semences, <i>càd</i>. les céréales, les plantes <i>en gén. seul. en poésie, au plur</i>. ESCHL. <i>Eum. 803 ;</i><br><b>      2</b> <i>en parl. de pers</i>. rejeton, descendant, enfant, <i>d’ord. au sg</i>. ESCHL. <i>Eum. 182, etc. ;</i> SOPH. <i>Ph. 364, etc. ;</i> EUR. <i>Bacch. 35 ;</i> ORACL. (THC. <i>5, 16) ; rar. au plur</i>. ESCHL. <i>Eum. 909 ;</i> SOPH. <i>O.R. 1246, etc. ; en prose,</i> PLAT. <i>Leg. 853</i> c, <i>etc. ;</i><br><b>   III</b> action de semer, semailles, σπέρματος ἄρξασθαι, commencer les semailles, HÉS. <i>O. 781</i>.<br><span><b>Étym</b>. σπείρω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σπερμα - σπέρμα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n44 fois dans 41 versets de 13 livres bibliques (NT)\n<ul>\n<li>Matthieu (7)</li>\n<li>Marc (5)</li>\n<li>Luc (2)</li>\n<li>Jean (3)</li>\n<li>Actes (4)</li>\n<li>Romains (9)</li>\n<li>1 Corinthiens (1)</li>\n<li>2 Corinthiens (2)</li>\n<li>Galates (5)</li>\n<li>2 Timothée (1)</li>\n<li>Hébreux (3)</li>\n<li>1 Jean (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G4691":"<h1>spermologos</h1>\n<p>Strong n° 4691 <i>Prononciation [sper-mol-og'-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>qui picore la semence\n<ol type=\"a\">\n<li>des oiseaux, en particulier corbeau ou choucas qui mangent les graines dans les champs</li>\n</ol>\n</li>\n<li>métaph.\n<ol type=\"a\">\n<li>celui qui fréquente les places de marchés pour récupérer tout ce qui peut tomber, avec un peu de chance, d'un chargement de marchandise</li>\n<li>de là, misérable, abject, vil, (un parasite)</li>\n<li>qui vit par flatterie et en faisant le bouffon</li>\n<li>un parleur vide, un babillard, un discoureur</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σπερμο·λόγος, ος, ον :<br>      1</b> qui ramasse <i>ou</i> picore des grains, ALEX. MYND. (ATH. <i>387</i> f) ; PLUT. <i>Demetr. 28 ; subst</i>. ὁ σπ. freux, <i>sorte de corbeau,</i> AR. <i>Av. 232, 579 ;</i> ARSTT. <i>H.A. 8, 36 ;</i><br><b>      2</b> qui ramasse, pour se nourrir, les grains épars sur le marché, <i>d’où</i> malheureux, misérable, gueux, DÉM. <i>269, 19 ;</i> DH. <i>Exc. t. 4, p. 2340 Reiske ;</i> NT. <i>Ap. 17, 18, etc</i>.<br><span>•<i> Sup</i>. -ώτατος, DH. <i>17, 6</i>.<br><span><b>Étym</b>. σπέρμα, λέγω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σπερμολογος - σπερμολόγος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4692":"<h1>speudo</h1>\n<p>Strong n° 4692 <i>Prononciation [spyoo'-do]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>hâter, accélérer</li>\n<li>désirer sérieusement, sincèrement</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σπεύδω</b> <span>(<i>f</i>. σπεύσω, <i>ao</i>. ἔσπευσα, <i>pf</i>. ἔσπευκα ; <i>pf. pass</i>. ἔσπευσμαι)</span><br><b>   I <i>tr. :</i><br>      1</b> presser, hâter : τι, IL. <i>13, 236,</i> qqe ch. ; γάμον, OD. <i>19, 137,</i> un mariage ; παῦσαι σπεύδων τὰ σπεύδεις, HDT. <i>7, 206,</i> cesse la hâte que tu montres ; <i>particul</i>. apporter en hâte, procurer avec empressement, tenir prêt, <i>acc</i>. SOL. <i>fr. 38 ;</i> EUR. <i>I.T. 1351 ;</i><br><b>      2</b> <i>abs</i>. presser, exhorter, exciter, HDT. <i>8, 46 ;</i><br><b>      3</b> rechercher avec empressement, être ardent pour : μηδὲν ἄγαν σπ. THGN. <i>335, 401,</i> ne faire de zèle en rien, n’être ardent à l’excès pour rien ; σπ. βίον ἀθάνατον, PD. <i>P. 3, 110 ;</i> ἀρετάν, PD. <i>I. 4, 22,</i> viser avec ardeur à l’immortalité, à la vertu ; τὴν ἡγεμονίαν, THC. <i>5, 16,</i> poursuivre avec ardeur le commandement ; σεαυτῷ τἀναντία σπεύδεις, PLAT. <i>Prot. 361</i> a, tu vises à la contradiction avec toi-même ; σπ. πόλεμόν τινι, EUR. <i>H.f. 1133,</i> livrer bataille à qqn ; <i>avec une prop. inf</i>. viser à ce que, <i>etc</i>. HDT. <i>1, 74 ;</i> XÉN. <i>Mem. 4, 3, 1 ;</i> PLAT. <i>Crit. 45 c. ;</i> SOPH. <i>Aj. 804, etc. ; avec une conj</i>. σπ. τι αἰ, IL. <i>13, 236 ;</i> ὅπως, PLAT. <i>Leg. 687</i> c, <i>etc</i>. presser vivement qqe ch. pour voir si, <i>etc</i>. pour que, <i>etc. ; au pass</i>. être recherché <i>ou</i> obtenu avec effort, HDT. <i>7, 53 ;</i> LUC. <i>Am. 33, etc. ;</i><br><b>   II <i>intr</i>.<br>      1</b> se hâter, se presser, IL. <i>8, 191 ; 23, 767 ;</i> HÉS. <i>Sc. 228 ;</i> SOPH. <i>El. 935, etc. ;</i> EUR. <i>Med. 183, etc. ;</i> AR. <i>Pl. 255, etc. ;</i> σπεύδειν ἀπὸ ῥυτῆρος, SOPH. <i>O.C. 900,</i> se hâter à bride abattue <i>càd</i>. en toute hâte ; σπ. ταχέως, AR. <i>Eq. 495 ;</i> θᾶσσον, EUR. <i>Med. 100 ;</i> ὅτι <i>ou</i> ὡς τάχιστα, IL. <i>23, 414 ;</i> AR. <i>Lys. 266,</i> se hâter vivement, plus vite, le plus vite possible ; σπεύδειν ἐς μάχην, IL. <i>4, 225,</i> s’élancer au combat ; σπ. πρός τινα, AR. <i>Vesp. 1026,</i> s’empresser vers qqn ; ἐπὶ βοήθειαν, LYCURG. <i>155, 10,</i> courir au secours ; <i>au part. au sens d’un adj. ou d’un adv. :</i> pressé, en hâte, vite : ἤϊξε σπεύδουσα, IL. <i>11, 119,</i> elle fuit en hâte ; <i>cf</i>. IL. <i>23, 506 ;</i> σπεύδων ἐϐοήθει, XÉN. <i>Hell. 4, 3, 1,</i> il accourait au secours ; <i>avec l’inf</i>. HÉS. <i>O. 671 ;</i> PD. <i>N. 9, 50 ; avec un part</i>. φέρων ἔσπευδον, AR. <i>Ach. 179,</i> je me hâtais d’apporter, <i>etc. ; cf</i>. SOPH. <i>El. 935, etc. ;</i> EUR. <i>Med. 761 ; avec une conj. :</i> σπ. ἵνα, IL. <i>15, 402 ;</i> ὡς, EUR. <i>Hel. 1438 ;</i> ὅπως, AR. <i>Lys. 266,</i> se hâter pour que, se hâter de, <i>etc. ;</i><br><b>      2</b> <i>en gén</i>. agir avec empressement, se donner de la peine, faire effort, s’efforcer, IL. <i>8, 293 ; 18, 373, 472 ; 24, 253 ;</i> OD. <i>24, 324 ;</i> HÉS. <i>O. 459, etc. ;</i> SOPH. <i>Ph. 620, etc. ; en parl. de combat,</i> IL. <i>4, 232 ; 5, 667, etc. ; de bêtes de trait,</i> IL. <i>17, 745 ; d’abeilles, etc</i>. HÉS. <i>Th. 597, etc. ;</i> σπεύδειν τινί, ALEX. (<i>Com. fr. 3, 525</i>) ; CHARIT. <i>6, 1,</i> se donner de la peine pour qqn, être dévoué à qqn : σπ. εἴς τι, HÉS. <i>O. 24 ;</i> THGN. <i>402 ;</i> ESCHL. <i>Pr. 192, etc. ;</i> THC. <i>5, 37, etc</i>. se donner de la peine, faire effort pour qqe ch. ; σπεύδειν περὶ Πατρόκλοιο θανόντος, IL. <i>17, 421,</i> faire effort pour Patrocle tombé, combattre pour son cadavre ; <i>de même avec</i> ὑπέρ <i>et le gén</i>. POL. <i>4, 51, 2 ; au part. au sens d’un adv. :</i> laborieusement, péniblement : σπεύδων ἕλκει ὁ πρέσϐυς κάμνοντι ἐοικώς, THCR. <i>Idyl. 7, 40,</i> le vieillard traîne péniblement (un grand filet) semblable à un homme qui déploie toute sa force ; <i>avec l’inf</i>. se donner de la peine pour, faire effort pour, HÉS. <i>O. 22, 671 ;</i> SOPH. <i>Aj. 812 ;</i> HDT. <i>8, 41 ;</i> XÉN. <i>An. 1, 3, 14, etc. ;</i> PLAT. <i>Rsp. 528</i> d, <i>etc. ; avec un part</i>. σπεῦσε πονησάμενος τὰ ἃ ἔργα, OD. <i>9, 250,</i> il avait accompli son travail rapidement ; <i>cf</i>. XÉN. <i>Hell. 3, 1, 17 ; avec une conj</i>. σπ. αἴ κε, IL. <i>17, 121 ;</i> ὡς, ESCHL. <i>Pr. 203 ;</i> ὅπως, AR. <i>Eq. 934 ;</i> ἵνα, PLAT. <i>Pol. 264</i> b, <i>etc.,</i> faire effort pour voir si., pour que., <i>etc. ;</i><br><b>      3</b> <i>abs</i>. se tourmenter, être agité, être inquiet, s’effrayer, SPT. <i>Ex. 15, 15 ; 1Reg. 28, 21, etc. ;</i><br><b><i>Moy.</i></b> <span>(<i>f</i>. σπεύσομαι)</span> s’occuper avec empressement de, <i>acc</i>. ESCHL. <i>Ag. 147</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Act. prés. ind. 3 pl. dor</i>. σπεύδοντι, THCR. <i>Idyl. 16, 15 ; sbj. 1 pl. dor</i>. σπεύδωμες, THCR. <i>Idyl. 15, 59 ; inf. épq</i>. σπευδέμεν, OD. <i>24, 324. Ao. sbj. 1 pl. épq</i>. σπεύσομεν (<i>p</i>. -ωμεν) IL. <i>17, 121. Pf. pass</i>. ἔσπευσμαι, GAL. <i>13, 487 dout</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *speud-, hâter.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σπευδω - σπεύδω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 6 versets de 3 livres bibliques (NT)\n<ul>\n<li>Luc (3)</li>\n<li>Actes (2)</li>\n<li>2 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G4693":"<h1>spelaion</h1>\n<p>Strong n° 4693 <i>Prononciation [spay'-lah-yon]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>une caverne, une antre, un repaire, une grotte</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σπήλαιον, ου (τὸ) :<br>      1</b> caverne, grotte, cavité, PLAT. <i>Rsp. 514</i> a, <i>515</i> a, <i>539</i> e, <i>etc. ;</i><br><b>      2</b> parties secrètes, SPT. <i>Hab. 2, 15</i>.<br><span><b>Étym</b>. <i>pré-grec, cf</i>. σπῆλυγξ ; <i>emprunts lat</i>. spēlæum, spēlunca.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σπηλαιον - σπήλαιον</font>\n<br><br>vient d'un dérivé présumé de speos (une grotte)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 6 versets de 6 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Luc (1)</li>\n<li>Jean (1)</li>\n<li>Hébreux (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G4694":"<h1>spilas</h1>\n<p>Strong n° 4694 <i>Prononciation [spee-las']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un rocher dans la mer, une barre, un récif</li>\n<li>métaph. des hommes qui, par leur conduite, démoralisent les autres, font faire naufrage</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σπιλάς, άδος (ἡ)</b> <span>[ῐᾰδ]</span><br><b>   I</b> <i>subst. :</i><br><b>      1</b> roc près de la mer <i>ou</i> en mer, écueil, OD. <i>3, 298 ; 5, 401 ;</i> SOPH. <i>fr. 341 Dind. ;</i> A. RH. <i>3, 1294 ; 4, 932 ;</i> POL. <i>1, 37, 2 ; etc. ;</i><br><b>      2</b> <i>p. anal</i>. point qui fait tache sur une surface comme un écueil sur la surface de la mer, ORPH. <i>Lith. 614 ;</i><br><b>   II</b> <i>adj. f. :</i> γῆ σπιλάς, TH. <i>C.P. 2, 4, 4 ; ou simpl</i>. σπιλάς, SOPH. <i>Tr. 675,</i> terre glaise, argile, sol d’argile.<br><span><b><span class=\"arrow\"></span></b> <i>Dat. pl. épq</i>. σπιλάδεσσι, OD. <i>5, 401 ;</i> SOPH. <i>fr. 341 ;</i> σπιλάδεσσιν, OD. <i>3, 298</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σπιλας - σπιλάς</font>\n<br><br>de dérivation incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Jude (1)</li>\n</ul>\n</td></tr>\n</table>","G4695":"<h1>spiloo</h1>\n<p>Strong n° 4695 <i>Prononciation [spee-lo'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>souiller, tacher, salir</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σπιλόω-ῶ</b> <span>[ῐ]</span> tacher, souiller, DH. <i>9, 6 ;</i> LUC. <i>Am. 15 ; fig</i>. NT. <i>Jac. 3, 6, etc</i>.<br><span><b>Étym</b>. σπίλος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σπιλοω - σπιλόω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Jacques (1)</li>\n<li>Jude (1)</li>\n</ul>\n</td></tr>\n</table>","G4696":"<h1>spilos</h1>\n<p>Strong n° 4696 <i>Prononciation [spee'-los]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une tache</li>\n<li>une faute, un défaut moral\n<ol type=\"a\">\n<li>des hommes primitifs et gloutons</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n➀ <b>σπίλος, ου (ὁ)</b> <span>[ῐ]</span> tache sur la peau, <i>d’où,</i> tache <i>en gén</i>. DORION (ATH. <i>297</i> c) ; JOS. <i>A.J. 13, 11, 3 ;</i> PLUT. <i>M. 921</i> f, <i>etc. ; fig</i>. impureté, vice, LYSIS (JAMBL. <i>V. Pyth. 162) ; en parl. de pers</i>. DH. <i>4, 24 ;</i> NT. <i>Eph. 5, 27</i>.<br><br>\n➁ <b>σπίλος, ου (ἡ)</b> <span>[ῐ]</span> roc, écueil, ION (HSCH.) ; ARSTT. <i>Mund. 3, 4 ;</i> M. RUBR. <i>p. 12 ;</i> LYC. <i>188, etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σπιλος - σπίλος</font>\n<br><br>dérivation incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Ephésiens (1)</li>\n<li>2 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G4697":"<h1>splagchnizomai</h1>\n<p>Strong n° 4697 <i>Prononciation [splangkh-nid'-zom-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>être remué dans ses intestins, de là être ému de compassion, avoir compassion (car les entrailles sont sensées être le siège de l'amour et de la pitié)</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σπλαγχνίζω</b> <span>(<i>f</i>. ίσω ; <i>f. pass</i>. -ισθήσομαι)</span><br><b>      1</b> manger les entrailles de la victime après le sacrifice, SPT. <i>2Macc. 6, 8 ;</i><br><b>      2</b> remuer les entrailles, <i>d’où au pass</i>. être touché, ému : περί τινος, NT. <i>Matth. 9, 36 ;</i> ἐπί τινα, NT. <i>Marc. 6, 34 ; 8, 2, etc</i>. être ému de pitié pour qqn.<br><span><b>Étym</b>. σπλάγχνον.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σπλαγχνιζομαι - σπλαγχνίζομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n12 fois dans 12 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (5)</li>\n<li>Marc (4)</li>\n<li>Luc (3)</li>\n</ul>\n</td></tr>\n</table>","G4698":"<h1>splagchnon</h1>\n<p>Strong n° 4698 <i>Prononciation [splangkh'-non]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>entrailles, intestins, (le cœur, les poumons, le foie, etc.)\n<ol type=\"a\">\n<li>entrailles</li>\n<li>les entrailles étaient considérées comme le siège des plus violentes passions, telles la colère et l'amour; mais par les Hébreux, le siège ses plus tendres affections, en particulier bonté, bienveillance, compassion; de là notre cœur</li>\n<li>un cœur dans lequel réside la miséricorde</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σπλάγχνον, ου (τὸ)</b> <i>d’ord. au pl</i>. σπλάγχνα, ων (τὰ) les entrailles :<br><b>   I</b> <i>au propre :</i><br><b>      1</b> les viscères principaux (cœur, poumon, foie) de l’homme <i>ou</i> des animaux, IL. <i>1, 464 ;</i> OD. <i>3, 9 et 40 ; 20, 252 ;</i> HDT. <i>2, 40 ;</i> ESCHL. <i>Ag. 1221 ;</i> AR. <i>Pax 1105, etc</i>. (σπλάγχνον <i>au sg</i>. s’emploie pour l’un de ces viscères, ESCHL. <i>Sept. 1031, Eum. 249 ;</i> PLAT. <i>Tim. 73</i> c) ; <i>p. suite,</i> le partage des entrailles de la victime pour le repas sacré, AR. <i>Vesp. 654, Eq. 408, etc. ;</i><br><b>      2</b> le sein de la mère, ESCHL. <i>Sept. 1022 ; en parl. du père,</i> SOPH. <i>Ant. 1066 ;</i><br><b>   II</b> <i>fig. :</i><br><b>      1</b> le cœur, l’âme <i>comme siège des affections,</i> ESCHL. <i>Ag. 995, Ch. 413 ;</i> SOPH. <i>Aj. 995 ;</i> EUR. <i>Hipp. 118, etc. ;</i> AR. <i>Ran. 844, 1006, Nub. 1036 ;</i> ANTH. <i>6, 260 ; 12, 80, etc. ; ou comme siège du caractère,</i> EUR. <i>Med. 220 ;</i><br><b>      2</b> entrailles, cœur, âme, <i>t. de tendresse,</i> NT. <i>Phil. 1, 8 ; 2, 1</i>.<br><span><b>Étym</b>. σπλήν.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σπλαγχνον - σπλάγχνον</font>\n<br><br>probablement renforcement de splen (mélancolie, le « spleen » anglais)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n11 fois dans 11 versets de 7 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Actes (1)</li>\n<li>2 Corinthiens (2)</li>\n<li>Philippiens (2)</li>\n<li>Colossiens (1)</li>\n<li>Philémon (3)</li>\n<li>1 Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G4699":"<h1>spoggos</h1>\n<p>Strong n° 4699 <i>Prononciation [spong'-gos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>éponge</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σπόγγος, ου (ὁ) :<br>      1</b> éponge, IL. <i>18, 414 ;</i> OD. <i>1, 111, etc. ;</i> ESCHL. <i>Ag. 1329 ;</i> AR. <i>Vesp. 600, etc. ;</i> PLAT. <i>Tim. 70</i> c ; ARSTT. <i>H.A. 1, 1, 18, etc. ;</i><br><b>      2</b> substance spongieuse, HPC. <i>679, 33 ; particul. au pl</i>. les amygdales, <i>glandes à l’entrée de la gorge, à cause de leur nature spongieuse,</i> HPC. <i>1121</i> e.<br><span><b>Étym</b>. <i>p</i>. *σφόγγος, <i>cf. lat</i>. fungus.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σπογγος - σπόγγος</font>\n<br><br>peut-être d'origine étrangère</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Jean (1)</li>\n</ul>\n</td></tr>\n</table>"};
